import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { db } from './firebaseConfig';
import { collection, doc, writeBatch, onSnapshot } from 'firebase/firestore';
import { encryptData, decryptData } from './encryption';
import {
  Box,
  Flex,
  Input,
  Button,
  Text,
  Badge,
  Divider,
  Checkbox,
  VStack,
  HStack,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  InputGroup,
  InputLeftAddon,
  InputRightAddon,
  useToast,
  useBreakpointValue,
  useDisclosure,
  Drawer,
  DrawerBody,
  DrawerHeader,
  DrawerOverlay,
  DrawerContent,
  DrawerCloseButton,
  Grid,
  Menu,
  MenuButton,
  MenuList,
  MenuItem
} from '@chakra-ui/react';

const HTML_ESCAPE_MAP = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;'
};

const escapeHtml = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (char) => HTML_ESCAPE_MAP[char]);

const formatCurrency = (value) => `\u20b1${(Number(value) || 0).toFixed(2)}`;
const BRAND_GREEN = '#065f2f';
const BRAND_GOLD = '#f4b41a';
const BRAND_GOLD_SOFT = '#fff6d8';
const codeSortCollator = new Intl.Collator(undefined, {
  numeric: true,
  sensitivity: 'base'
});

const TABLE_COLUMN_PROPS = {
  code: { w: { base: '72px', md: '90px', lg: '78px' }, flexShrink: 0 },
  name: { flex: { base: '0 0 230px', md: '0 0 320px', lg: '1 1 auto' }, minW: 0 },
  category: { w: { base: '112px', md: '132px', lg: '96px' }, flexShrink: 0 },
  stock: { w: { base: '66px', md: '82px', lg: '80px' }, flexShrink: 0 },
  price: { w: { base: '90px', md: '104px', lg: '90px' }, flexShrink: 0 },
  qty: { w: { base: '68px', md: '78px', lg: '70px' }, flexShrink: 0 }
};

const PH_ONLINE_PAYMENTS = [
  'GCash',
  'Maya',
  'GrabPay',
  'BDO Online',
  'BPI Online',
  'UnionBank',
  'Other Bank Transfer',
  'Credit Card'
];

const getProductUniqueId = (item) => String(item?.code || item?.itemId || item?.id || '').trim();
const getProductKey = (item) => getProductUniqueId(item).toLowerCase();

const sortProductsByCode = (a, b) => {
  const codeA = String(a.code || '').trim();
  const codeB = String(b.code || '').trim();

  if (codeA && codeB) {
    const codeCompare = codeSortCollator.compare(codeA, codeB);
    if (codeCompare !== 0) return codeCompare;
  } else if (codeA) {
    return -1;
  } else if (codeB) {
    return 1;
  }

  return codeSortCollator.compare(String(a.name || ''), String(b.name || ''));
};

const formatPoDate = (timestamp) => {
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return '-';

  return `${date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric'
  })} - ${date.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit'
  })}`;
};

const getOrderNumber = (receiptData) =>
  receiptData.orderNumber ||
  receiptData.poNumber ||
  receiptData.receiptNumber ||
  receiptData.id ||
  '-';

const buildPurchaseOrderHtml = (receiptData) => {
  const itemRows = (receiptData.items || [])
    .map((item) => {
      const qty = Number(item.qty) || 0;
      const price = Number(item.price) || 0;
      const lineTotal = Number(item.lineTotal) || price * qty;

      return `
        <tr>
          <td class="code-col">${escapeHtml(item.code || '-')}</td>
          <td>
            <div class="item-name">${escapeHtml(item.name)}</div>
          </td>
          <td class="qty">${escapeHtml(qty)}</td>
          <td class="price">${escapeHtml(formatCurrency(price))}</td>
          <td class="amount">${escapeHtml(formatCurrency(lineTotal))}</td>
        </tr>
      `;
    })
    .join('');

  const vatRow = receiptData.applyVat
    ? `
      <div class="total-line muted">
        <span>VAT (12%)</span>
        <span>+ ${escapeHtml(formatCurrency(receiptData.vatAmount))}</span>
      </div>
    `
    : '';

  const discountRows = receiptData.isSeniorOrPWD
    ? `
      <div class="total-line muted">
        <span>Discount (${escapeHtml(receiptData.discountPercent)}%)</span>
        <span>- ${escapeHtml(formatCurrency(receiptData.discountAmount))}</span>
      </div>
    `
    : '';

  const manualTotalRow = receiptData.wasManuallyOverridden
    ? `
      <div class="total-line muted">
        <span>Manual Total</span>
        <span>Applied</span>
      </div>
    `
    : '';

  return `<!doctype html>
    <html>
      <head>
        <meta charset="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <title>P.O Purchase Order</title>
        <style>
          @page { size: A4; margin: 18mm; }
          * { box-sizing: border-box; }
          html, body {
            margin: 0;
            padding: 0;
            background: #ffffff;
            color: ${BRAND_GREEN};
            font-family: Arial, Helvetica, sans-serif;
            font-size: 15px;
            line-height: 1.35;
          }
          body {
            min-width: 0;
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
          }
          .page {
            width: 100%;
            max-width: 760px;
            margin: 0 auto;
            padding: 72px 56px;
          }
          .header {
            display: grid;
            grid-template-columns: 1fr auto;
            gap: 32px;
            align-items: start;
          }
          h1 {
            margin: 0 0 16px;
            color: ${BRAND_GREEN};
            font-size: 29px;
            font-weight: 800;
            letter-spacing: 1px;
          }
          .meta, .brand-block { font-size: 15px; }
          .brand-block {
            min-width: 150px;
            padding-top: 16px;
          }
          .accent {
            height: 2px;
            margin: 34px 0 30px;
            background: linear-gradient(90deg, ${BRAND_GREEN} 0%, ${BRAND_GREEN} 68%, ${BRAND_GOLD} 68%, ${BRAND_GOLD} 100%);
          }
          table {
            width: 100%;
            border-collapse: collapse;
          }
          th {
            background: ${BRAND_GOLD_SOFT};
            border-bottom: 2px solid ${BRAND_GREEN};
            padding: 11px 12px;
            color: ${BRAND_GREEN};
            font-size: 15px;
            font-weight: 800;
            text-align: left;
          }
          td {
            padding: 13px 12px;
            border-bottom: 1px solid #eeeeee;
            vertical-align: top;
          }
          .code-col {
            width: 100px;
            word-break: break-all;
          }
          .item-name {
            font-weight: 500;
            text-transform: uppercase;
            overflow-wrap: anywhere;
          }
          .qty, .price, .amount {
            width: 90px;
            text-align: right;
            white-space: nowrap;
          }
          .totals {
            display: flex;
            justify-content: flex-end;
            margin-top: 28px;
          }
          .total-box { min-width: 260px; }
          .total-line {
            display: flex;
            justify-content: space-between;
            gap: 24px;
            margin-bottom: 8px;
          }
          .muted {
            color: #667085;
            font-size: 14px;
          }
          .grand-total {
            color: ${BRAND_GREEN};
            font-size: 23px;
            font-weight: 900;
          }
          .footer {
            margin-top: 56px;
            color: #667085;
            text-align: center;
            font-size: 12px;
            font-style: italic;
          }
          .actions {
            display: flex;
            justify-content: center;
            gap: 10px;
            margin-top: 36px;
          }
          .actions button {
            border: 1px solid ${BRAND_GREEN};
            border-radius: 4px;
            background: ${BRAND_GREEN};
            color: #ffffff;
            padding: 9px 14px;
            font-size: 13px;
            font-weight: 700;
            cursor: pointer;
          }
          .actions button.secondary {
            border-color: ${BRAND_GOLD};
            background: ${BRAND_GOLD_SOFT};
            color: ${BRAND_GREEN};
          }
          @media screen {
            body {
              padding: 18px;
              background: #2b2b2b;
            }
            .page {
              min-height: 1040px;
              background: #ffffff;
              box-shadow: 0 18px 45px rgba(0, 0, 0, 0.24);
            }
          }
          @media print {
            html, body {
              width: auto;
              height: auto;
              min-height: 0;
              overflow: visible;
            }
            .page {
              width: 100%;
              max-width: none;
              margin: 0;
              padding: 0;
              box-shadow: none;
              page-break-after: avoid;
              break-after: avoid;
            }
            .no-print { display: none !important; }
            tr, .totals, .footer {
              page-break-inside: avoid;
              break-inside: avoid;
            }
          }
          @media (max-width: 640px) {
            .page { padding: 42px 22px; }
            .header {
              grid-template-columns: 1fr;
              gap: 12px;
            }
            .brand-block { padding-top: 0; }
            h1 { font-size: 24px; }
            .code-col { width: auto; }
            .qty, .price, .amount { width: auto; }
          }
        </style>
      </head>
      <body>
        <main class="page">
          <section class="header">
            <div>
              <h1>P.O PURCHASE ORDER</h1>
              <div class="meta">
                <div style="margin-bottom: 4px;"><strong>Name:</strong> ${escapeHtml(receiptData.customerName || 'Walk-in Customer')}</div>
                ${receiptData.customerAddress ? `<div style="margin-bottom: 4px;"><strong>Address:</strong> ${escapeHtml(receiptData.customerAddress)}</div>` : ''}
                <div style="margin-top: 12px;">Order #: ${escapeHtml(getOrderNumber(receiptData))}</div>
              </div>
            </div>
            <div class="brand-block">
              <div style="text-align: right;">${escapeHtml(formatPoDate(receiptData.timestamp))}</div>
            </div>
          </section>
          <div class="accent"></div>
          <table>
            <thead>
              <tr>
                <th class="code-col">Code</th>
                <th>Item</th>
                <th class="qty">Qty</th>
                <th class="price">Price</th>
                <th class="amount">Total</th>
              </tr>
            </thead>
            <tbody>${itemRows}</tbody>
          </table>
          <section class="totals">
            <div class="total-box">
              <div class="total-line muted">
                <span>Subtotal</span>
                <span>${escapeHtml(formatCurrency(receiptData.rawTotal))}</span>
              </div>
              ${vatRow}
              ${discountRows}
              ${manualTotalRow}
              <div class="total-line grand-total">
                <span>Total:</span>
                <span>${escapeHtml(formatCurrency(receiptData.finalTotal))}</span>
              </div>
            </div>
          </section>
          <div class="footer">This purchase order was generated electronically.</div>
          <div class="actions no-print">
            <button type="button" onclick="window.print()">Print P.O.</button>
            <button type="button" class="secondary" onclick="window.close()">Close</button>
          </div>
        </main>
      </body>
    </html>`;
};

const ProductRow = memo(function ProductRow({
  item,
  currentRowQty,
  fontSize,
  onAddToCart,
  onRowQtyChange
}) {
  const isOutOfStock = item.stock <= 0;
  const isLowStock = item.stock > 0 && item.stock <= 5;

  return (
    <Flex
      align="center"
      px={{ base: 2, md: 4 }}
      py={{ base: 2, md: 2 }}
      borderBottomWidth="1px"
      borderColor="gray.100"
      opacity={isOutOfStock ? 0.5 : 1}
      bg={isOutOfStock ? 'red.50' : 'white'}
      _hover={{ bg: isOutOfStock ? 'red.50' : 'blue.50' }}
      transition="background 0.15s"
      gap={2}
    >
      <Text
        fontSize="xs"
        fontWeight="bold"
        color={item.code ? 'blue.600' : 'gray.400'}
        display="block"
        noOfLines={1}
        {...TABLE_COLUMN_PROPS.code}
      >
        {item.code || '-'}
      </Text>

      <Box
        cursor={isOutOfStock ? 'not-allowed' : 'pointer'}
        onClick={() => onAddToCart(item)}
        {...TABLE_COLUMN_PROPS.name}
      >
        <Text
          fontWeight="semibold"
          fontSize={fontSize}
          whiteSpace="normal"
          overflowWrap="anywhere"
          lineHeight="1.25"
        >
          {item.name}
        </Text>
      </Box>

      <Box display="block" {...TABLE_COLUMN_PROPS.category}>
        <Badge colorScheme="teal" fontSize="0.6em" maxW="100%">
          <Text as="span" noOfLines={1}>
            {item.category || 'General'}
          </Text>
        </Badge>
      </Box>

      <Text
        fontSize="xs"
        textAlign="center"
        display="block"
        color={isOutOfStock ? 'red.500' : isLowStock ? 'orange.500' : 'gray.500'}
        fontWeight={isLowStock ? 'bold' : 'normal'}
        {...TABLE_COLUMN_PROPS.stock}
      >
        {isOutOfStock ? 'Out' : item.stock}
      </Text>

      <Text
        color="brandBlue.600"
        fontWeight="900"
        fontSize={fontSize}
        textAlign="right"
        {...TABLE_COLUMN_PROPS.price}
      >
        &#8369;{(Number(item.price) || 0).toFixed(2)}
      </Text>

      <Box pl={1} {...TABLE_COLUMN_PROPS.qty}>
        <Input
          size="sm"
          type="number"
          min={0}
          max={item.stock}
          value={currentRowQty}
          placeholder="-"
          textAlign="center"
          isDisabled={isOutOfStock}
          fontSize="xs"
          bg={currentRowQty >= 1 ? 'blue.50' : 'white'}
          borderColor={currentRowQty >= 1 ? 'blue.300' : 'gray.200'}
          _focus={{ borderColor: 'brandBlue.500', boxShadow: 'none' }}
          onClick={(e) => e.stopPropagation()}
          onChange={(e) => onRowQtyChange(item, e.target.value)}
          onWheel={(e) => e.target.blur()}
          px={1}
        />
      </Box>
    </Flex>
  );
});

const CartLine = memo(function CartLine({
  item,
  fontSize,
  onRemove,
  onUpdate
}) {
  return (
    <Box p={{ base: 2, md: 2 }} bg="gray.50" borderRadius="md" borderWidth="1px">
      <Flex justify="space-between" mb={1} align="center">
        <Box flex={1} minW={0} mr={1}>
          <Text fontWeight="bold" fontSize={fontSize} noOfLines={1}>
            {item.name}
          </Text>
          <HStack spacing={1} mt={1} flexWrap="wrap">
            {item.code && (
              <Badge colorScheme="blue" variant="subtle" fontSize="0.6em">
                {item.code}
              </Badge>
            )}
          </HStack>
        </Box>
        <Button size="xs" colorScheme="red" variant="ghost" onClick={() => onRemove(item)}>
          X
        </Button>
      </Flex>

      <HStack spacing={1}>
        <InputGroup size="sm" flex={1} minW={0}>
          <InputLeftAddon bg="transparent" border="none" px={1}>
            <Text fontSize="xs">&#8369;</Text>
          </InputLeftAddon>
          <Input
            type="number"
            value={item.price}
            onChange={(e) => onUpdate(item, 'price', e.target.value)}
            textAlign="right"
            bg="white"
            fontSize="xs"
            onWheel={(e) => e.target.blur()}
          />
        </InputGroup>

        <Text fontSize="xs" color="gray.500" flexShrink={0}>
          x
        </Text>

        <Input
          size="sm"
          w={{ base: '44px', md: '50px' }}
          type="number"
          value={item.qty}
          onChange={(e) => onUpdate(item, 'qty', e.target.value)}
          textAlign="center"
          bg="white"
          fontSize="xs"
          flexShrink={0}
          onWheel={(e) => e.target.blur()}
        />

        <Text
          fontWeight="bold"
          color="brandBlue.600"
          w={{ base: '68px', md: '84px' }}
          textAlign="right"
          fontSize="xs"
          flexShrink={0}
        >
          &#8369;{((Number(item.price) || 0) * (Number(item.qty) || 0)).toFixed(2)}
        </Text>
      </HStack>
    </Box>
  );
});

// --- ENCRYPTION HELPER ---
const encryptOrderObject = (order) => {
  const payload = {};
  if (order.customerName !== undefined) payload.customerName = encryptData(order.customerName);
  if (order.customerAddress !== undefined) payload.customerAddress = encryptData(order.customerAddress);
  
  if (order.paymentMethod !== undefined) payload.paymentMethod = encryptData(order.paymentMethod);
  if (order.items !== undefined) {
    payload.items = order.items.map((item) => ({
      itemId: encryptData(item.itemId),
      inventoryId: encryptData(item.inventoryId),
      code: encryptData(item.code),
      name: encryptData(item.name),
      qty: encryptData(String(item.qty)),
      price: encryptData(String(item.price)),
      lineTotal: encryptData(String(item.lineTotal))
    }));
  }
  if (order.rawTotal !== undefined) payload.rawTotal = encryptData(String(order.rawTotal));
  if (order.vatableSales !== undefined) payload.vatableSales = encryptData(String(order.vatableSales));
  if (order.vatAmount !== undefined) payload.vatAmount = encryptData(String(order.vatAmount));
  if (order.vatExemptSales !== undefined) payload.vatExemptSales = encryptData(String(order.vatExemptSales));
  if (order.discountAmount !== undefined) payload.discountAmount = encryptData(String(order.discountAmount));
  if (order.finalTotal !== undefined) payload.finalTotal = encryptData(String(order.finalTotal));
  if (order.isSeniorOrPWD !== undefined) payload.isSeniorOrPWD = order.isSeniorOrPWD;
  if (order.applyVat !== undefined) payload.applyVat = order.applyVat;
  if (order.discountPercent !== undefined) payload.discountPercent = encryptData(String(order.discountPercent));
  if (order.timestamp !== undefined) payload.timestamp = order.timestamp; 
  if (order.wasManuallyOverridden !== undefined) payload.wasManuallyOverridden = order.wasManuallyOverridden;
  if (order.status !== undefined) payload.status = encryptData(order.status);
  if (order.cancelledAt !== undefined) payload.cancelledAt = encryptData(order.cancelledAt);
  return payload;
};

export default function POS() {
  const [items, setItems] = useState([]);
  const [cart, setCart] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [isSeniorOrPWD, setIsSeniorOrPWD] = useState(false);
  const [applyVat, setApplyVat] = useState(false);
  const [discountPercent, setDiscountPercent] = useState(20);
  const [customTotal, setCustomTotal] = useState('');
  const [rowQtys, setRowQtys] = useState({});

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [customerAddress, setCustomerAddress] = useState(''); 
  const [receiptData, setReceiptData] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const isMobile = useBreakpointValue({ base: true, lg: false });
  const inputSize = useBreakpointValue({ base: 'sm', md: 'md' });
  const fontSize = useBreakpointValue({ base: 'xs', md: 'sm' });
  const headerFontSize = useBreakpointValue({ base: 'sm', md: 'lg' });
  const badgePx = useBreakpointValue({ base: 2, md: 4 });
  const badgePy = useBreakpointValue({ base: 1, md: 2 });

  const { isOpen: isCartOpen, onOpen: onCartOpen, onClose: onCartClose } = useDisclosure();
  const { isOpen: isOnlineMenuOpen, onOpen: onOnlineMenuOpen, onClose: onOnlineMenuClose } = useDisclosure();
  
  const toast = useToast();

  const inventoryByKeyRef = useRef(new Map());
  const cartQtyByKeyRef = useRef(new Map());
  const searchClearTimerRef = useRef(null);

  useEffect(() => {
    const unsubscribe = onSnapshot(
      collection(db, 'inventory'),
      (snapshot) => {
        setItems(snapshot.docs.map((docSnap) => {
          const data = docSnap.data();
          return {
            id: docSnap.id,
            code: decryptData(data.code),
            codeLower: decryptData(data.codeLower),
            name: decryptData(data.name),
            nameLower: decryptData(data.nameLower),
            supplierName: decryptData(data.supplierName),
            supplierNameLower: decryptData(data.supplierNameLower),
            category: decryptData(data.category),
            categoryLower: decryptData(data.categoryLower),
            price: Number(decryptData(data.price)) || 0,
            stock: Number(decryptData(data.stock)) || 0,
            isActive: data.isActive
          };
        }));
      },
      (error) => {
        toast({
          title: 'Unable to load inventory',
          description: error.message,
          status: 'error',
          position: 'top'
        });
      }
    );

    return () => unsubscribe();
  }, [toast]);

  const inventoryByKey = useMemo(() => {
    const map = new Map();
    items.forEach((item) => map.set(getProductKey(item), item));
    return map;
  }, [items]);

  useEffect(() => {
    inventoryByKeyRef.current = inventoryByKey;
  }, [inventoryByKey]);

  const cartQtyByKey = useMemo(() => {
    const map = new Map();
    cart.forEach((item) => map.set(getProductKey(item), Number(item.qty) || 0));
    return map;
  }, [cart]);

  useEffect(() => {
    cartQtyByKeyRef.current = cartQtyByKey;
  }, [cartQtyByKey]);

  useEffect(
    () => () => {
      if (searchClearTimerRef.current) window.clearTimeout(searchClearTimerRef.current);
    },
    []
  );

  const categories = useMemo(
    () => ['All', ...new Set(items.map((item) => item.category || 'General'))],
    [items]
  );

  const filteredItems = useMemo(() => {
    const searchLower = (searchTerm || '').toLowerCase();

    return items
      .filter((item) => {
        const matchesSearch =
          (item.name || '').toLowerCase().includes(searchLower) ||
          (item.code || '').toLowerCase().includes(searchLower) ||
          (item.supplierName || '').toLowerCase().includes(searchLower) ||
          (item.category || '').toLowerCase().includes(searchLower);

        return matchesSearch && (selectedCategory === 'All' || (item.category || 'General') === selectedCategory);
      })
      .sort(sortProductsByCode);
  }, [items, searchTerm, selectedCategory]);

  const sortedCart = useMemo(() => [...cart].sort(sortProductsByCode), [cart]);

  const totals = useMemo(() => {
    const rawTotalValue = cart.reduce(
      (acc, item) => acc + (Number(item.price) || 0) * (Number(item.qty) || 0),
      0
    );

    let currentTotal = rawTotalValue;
    let vatAmountValue = 0;

    if (applyVat) {
      vatAmountValue = rawTotalValue * 0.12;
      currentTotal += vatAmountValue;
    }

    let discountAmountValue = 0;
    if (isSeniorOrPWD) {
      const discountPct = (Number(discountPercent) || 0) / 100;
      discountAmountValue = currentTotal * discountPct;
      currentTotal -= discountAmountValue;
    }

    return {
      rawTotal: rawTotalValue,
      vatableSales: applyVat ? rawTotalValue : 0,
      vatAmount: vatAmountValue,
      vatExemptSales: applyVat ? 0 : rawTotalValue,
      discountAmount: discountAmountValue,
      computedFinal: currentTotal,
      finalTotal: customTotal !== '' ? Number(customTotal) : currentTotal
    };
  }, [cart, customTotal, isSeniorOrPWD, discountPercent, applyVat]);

  const compactItems = useMemo(
    () =>
      sortedCart.map((item) => ({
        itemId: item.inventoryId || item.id || getProductUniqueId(item),
        inventoryId: item.inventoryId || item.id,
        code: item.code || '',
        name: item.name || '',
        qty: Number(item.qty) || 0,
        price: Number(item.price) || 0,
        lineTotal: (Number(item.price) || 0) * (Number(item.qty) || 0)
      })),
    [sortedCart]
  );

  const deferSearchClear = useCallback(() => {
    if (!searchTerm) return;
    if (searchClearTimerRef.current) window.clearTimeout(searchClearTimerRef.current);

    searchClearTimerRef.current = window.setTimeout(() => {
      setSearchTerm('');
      searchClearTimerRef.current = null;
    }, 80);
  }, [searchTerm]);

  const handleRowQtyChange = useCallback(
    (item, value) => {
      const productKey = getProductKey(item);

      if (value === '') {
        setRowQtys((prev) => ({ ...prev, [productKey]: '' }));
        cartQtyByKeyRef.current.set(productKey, 0);
        setCart((prev) => prev.filter((cartItem) => getProductKey(cartItem) !== productKey));
        return;
      }

      let qty = parseInt(value, 10);

      if (Number.isNaN(qty) || qty < 0) qty = 0;

      if (qty > item.stock) {
        toast({
          title: `Only ${item.stock} in stock for "${item.name}"`,
          status: 'warning',
          duration: 1600,
          isClosable: true,
          position: 'top'
        });
        qty = item.stock;
      }

      cartQtyByKeyRef.current.set(productKey, qty);
      setRowQtys((prev) => ({ ...prev, [productKey]: qty }));
      setCustomTotal('');

      if (qty >= 1) {
        setCart((prev) => {
          const existing = prev.find((cartItem) => getProductKey(cartItem) === productKey);

          if (existing) {
            return prev.map((cartItem) =>
              getProductKey(cartItem) === productKey ? { ...cartItem, qty } : cartItem
            );
          }

          return [...prev, { ...item, inventoryId: item.id, itemId: getProductUniqueId(item), qty }];
        });
      } else {
        setCart((prev) => prev.filter((cartItem) => getProductKey(cartItem) !== productKey));
      }
    },
    [toast]
  );

  const addToCart = useCallback(
    (item) => {
      if (item.stock <= 0) {
        return toast({ title: 'Out of stock!', status: 'error', duration: 1600, position: 'top' });
      }

      const productKey = getProductKey(item);
      const currentQty = cartQtyByKeyRef.current.get(productKey) || 0;
      const newQty = currentQty + 1;

      if (newQty > item.stock) {
        return toast({ title: 'Stock limit reached!', status: 'warning', duration: 1600, position: 'top' });
      }

      cartQtyByKeyRef.current.set(productKey, newQty);
      setRowQtys((prev) => ({ ...prev, [productKey]: newQty }));
      setCustomTotal('');
      deferSearchClear();

      setCart((prev) => {
        const existing = prev.find((cartItem) => getProductKey(cartItem) === productKey);

        if (existing) {
          return prev.map((cartItem) =>
            getProductKey(cartItem) === productKey ? { ...cartItem, qty: newQty } : cartItem
          );
        }

        return [...prev, { ...item, inventoryId: item.id, itemId: getProductUniqueId(item), qty: 1 }];
      });

      return null;
    },
    [deferSearchClear, toast]
  );

  const removeFromCart = useCallback((item) => {
    const productKey = getProductKey(item);

    cartQtyByKeyRef.current.set(productKey, 0);
    setCart((prev) => prev.filter((cartItem) => getProductKey(cartItem) !== productKey));
    setRowQtys((prev) => ({ ...prev, [productKey]: '' }));
    setCustomTotal('');
  }, []);

  const updateCartItem = useCallback((item, field, value) => {
    const productKey = getProductKey(item);

    setCustomTotal('');

    setCart((prev) =>
      prev.map((cartItem) => {
        if (getProductKey(cartItem) !== productKey) return cartItem;

        let newQty = cartItem.qty;
        let newPrice = cartItem.price;

        if (field === 'qty') {
          newQty = value === '' ? '' : parseInt(value, 10);
          const liveItem = inventoryByKeyRef.current.get(productKey);
          const currentStock = liveItem ? liveItem.stock : cartItem.stock;

          if (newQty > currentStock) newQty = currentStock;

          cartQtyByKeyRef.current.set(productKey, Number(newQty) || 0);
          setRowQtys((prevRows) => ({ ...prevRows, [productKey]: newQty }));
        } else if (field === 'price') {
          newPrice = value === '' ? '' : parseFloat(value) || 0;
        }

        return { ...cartItem, qty: newQty, price: newPrice };
      })
    );
  }, []);

  const printPurchaseOrderFor = useCallback(
    (receipt) => {
      if (!receipt) return;

      const printWindow = window.open('', '_blank', 'width=900,height=900');

      if (!printWindow) {
        toast({
          title: 'Print window blocked',
          description: 'Please allow pop-ups for this site, then press Print P.O. again.',
          status: 'warning',
          duration: 4000,
          position: 'top',
          isClosable: true
        });
        return;
      }

      printWindow.document.open();
      printWindow.document.write(buildPurchaseOrderHtml(receipt));
      printWindow.document.close();

      const triggerPrint = () => {
        printWindow.focus();
        printWindow.print();
      };

      if (printWindow.document.readyState === 'complete') {
        window.setTimeout(triggerPrint, 350);
      } else {
        printWindow.onload = () => window.setTimeout(triggerPrint, 350);
      }
    },
    [toast]
  );

  const printPurchaseOrder = useCallback(() => {
    printPurchaseOrderFor(receiptData);
  }, [printPurchaseOrderFor, receiptData]);

  const openOnlineMenuIfCartHasItems = () => {
    if (cart.length === 0) return;
    onOnlineMenuOpen();
  };

  const processTransaction = async (e) => {
    e.preventDefault();

    if (!customerName) return;

    setIsProcessing(true);

    try {
      const batch = writeBatch(db);

      for (const cartItem of cart) {
        const productKey = getProductKey(cartItem);
        const liveItem = inventoryByKey.get(productKey);
        const currentStock = liveItem ? liveItem.stock : cartItem.stock;
        const inventoryDocId = liveItem?.id || cartItem.inventoryId || cartItem.id;

        if (currentStock < Number(cartItem.qty)) {
          toast({
            title: `Insufficient stock for "${cartItem.name}"`,
            description: `Available: ${currentStock}, Requested: ${cartItem.qty}`,
            status: 'error',
            duration: 3000,
            position: 'top'
          });
          setIsProcessing(false);
          return;
        }

        const newStock = currentStock - Number(cartItem.qty);
        batch.update(doc(db, 'inventory', inventoryDocId), { 
          stock: encryptData(String(newStock))
        });
      }

      const orderData = {
        customerName,
        customerAddress, 
        paymentMethod,
        items: compactItems,
        rawTotal: totals.rawTotal,
        vatableSales: totals.vatableSales,
        vatAmount: totals.vatAmount,
        vatExemptSales: totals.vatExemptSales,
        discountAmount: totals.discountAmount,
        finalTotal: totals.finalTotal,
        isSeniorOrPWD,
        applyVat,
        discountPercent: isSeniorOrPWD ? Number(discountPercent) : 0,
        timestamp: new Date().toISOString(),
        wasManuallyOverridden: customTotal !== ''
      };

      const saleRef = doc(collection(db, 'sales'));

      const encryptedOrderData = encryptOrderObject(orderData);
      batch.set(saleRef, encryptedOrderData);

      setReceiptData({ ...orderData, id: saleRef.id });
      setCart([]);
      cartQtyByKeyRef.current = new Map();
      setRowQtys({});
      setIsSeniorOrPWD(false);
      setApplyVat(false);
      setDiscountPercent(20);
      setShowPaymentModal(false);
      setCustomerName('');
      setCustomerAddress('');
      setCustomTotal('');
      setIsProcessing(false);

      if (isMobile) onCartClose();

      await batch.commit();
    } catch (error) {
      toast({ title: 'Error', description: error.message, status: 'error', position: 'top' });
      setIsProcessing(false);
    }
  };

  const CartUI = (
    <Box
      bg="white"
      p={{ base: 3, md: 4 }}
      borderRadius="lg"
      shadow={isMobile ? 'none' : 'sm'}
      h="100%"
      display="flex"
      flexDir="column"
      minH={0}
    >
      {!isMobile && (
        <>
          <Text fontSize={headerFontSize} fontWeight="bold" mb={2} flexShrink={0}>
            Current Order
          </Text>
          <Divider mb={3} flexShrink={0} />
        </>
      )}

      <VStack
        flex={{ base: '0 0 auto', lg: 1 }}
        minH={{ base: 'auto', lg: 0 }}
        overflowY={{ base: 'visible', lg: 'auto' }}
        overflowX="visible"
        spacing={0}
        align="stretch"
        pr={{ base: 0, lg: 1 }}
        sx={{
          '&::-webkit-scrollbar': { width: '4px' },
          '&::-webkit-scrollbar-thumb': { bg: 'gray.300', borderRadius: 'full' }
        }}
      >
        {cart.length === 0 && (
          <Text textAlign="center" color="gray.400" mt={10} fontSize={fontSize}>
            Select items to begin
          </Text>
        )}

        {sortedCart.map((item) => (
          <CartLine
            key={getProductKey(item)}
            item={item}
            fontSize={fontSize}
            onRemove={removeFromCart}
            onUpdate={updateCartItem}
          />
        ))}
      </VStack>

      <Box mt={3} pt={3} borderTopWidth="1px" flexShrink={0}>
        <HStack mb={2} spacing={4}>
          <Checkbox
            colorScheme="teal"
            size="sm"
            isChecked={applyVat}
            onChange={(e) => {
              setApplyVat(e.target.checked);
              setCustomTotal('');
            }}
          >
            <Text fontSize={{ base: 'xs', md: 'sm' }}>Add 12% VAT</Text>
          </Checkbox>
        </HStack>

        <HStack mb={2} align="center">
          <Checkbox
            colorScheme="yellow"
            size="sm"
            isChecked={isSeniorOrPWD}
            onChange={(e) => {
              setIsSeniorOrPWD(e.target.checked);
              setCustomTotal('');
            }}
          >
            <Text fontSize={{ base: 'xs', md: 'sm' }} whiteSpace="nowrap">Apply Discount</Text>
          </Checkbox>

          {isSeniorOrPWD && (
            <InputGroup size="sm" w="80px">
              <Input
                type="number"
                value={discountPercent}
                onChange={(e) => {
                  setDiscountPercent(e.target.value);
                  setCustomTotal('');
                }}
                textAlign="center"
                px={1}
              />
              <InputRightAddon px={2}>%</InputRightAddon>
            </InputGroup>
          )}
        </HStack>

        <Flex justify="space-between" fontSize={{ base: 'xs', md: 'sm' }} color="gray.600" mb={1}>
          <Text>Subtotal:</Text>
          <Text>&#8369;{totals.rawTotal.toFixed(2)}</Text>
        </Flex>

        {applyVat && (
          <Flex justify="space-between" fontSize={{ base: 'xs', md: 'sm' }} color="gray.600" mb={1}>
            <Text>VAT (12%):</Text>
            <Text>+ &#8369;{totals.vatAmount.toFixed(2)}</Text>
          </Flex>
        )}

        {isSeniorOrPWD && (
          <Flex justify="space-between" fontSize={{ base: 'xs', md: 'sm' }} color="red.500" mb={2}>
            <Text>Discount ({discountPercent}%):</Text>
            <Text>- &#8369;{totals.discountAmount.toFixed(2)}</Text>
          </Flex>
        )}

        <Flex
          justify="space-between"
          align="center"
          mt={2}
          pt={2}
          borderTopWidth="2px"
          borderTopStyle="dashed"
          borderColor="blue.200"
          gap={2}
        >
          <Text fontSize={{ base: 'sm', md: 'md' }} fontWeight="black" flexShrink={0}>
            Total Due:
          </Text>
          <HStack spacing={1} minW={0}>
            <Text fontWeight="bold" fontSize={fontSize}>
              &#8369;
            </Text>
            <Input
              size={{ base: 'sm', md: 'md' }}
              fontWeight="black"
              w={{ base: '104px', md: '126px' }}
              textAlign="right"
              bg="blue.50"
              borderColor="blue.300"
              focusBorderColor="brandBlue.500"
              type="number"
              fontSize={fontSize}
              value={customTotal !== '' ? customTotal : totals.computedFinal.toFixed(2)}
              onChange={(e) => setCustomTotal(e.target.value)}
              onWheel={(e) => e.target.blur()}
            />
          </HStack>
        </Flex>

        <HStack mt={3} spacing={2}>
          <Button
            flex={1}
            colorScheme="teal"
            size={inputSize}
            fontSize={fontSize}
            isDisabled={cart.length === 0}
            onClick={() => {
              setPaymentMethod('Cash');
              setShowPaymentModal(true);
            }}
          >
            Cash
          </Button>

          {/* ONLINE PAYMENT MENU */}
          <Box 
            flex={1} 
            onMouseEnter={openOnlineMenuIfCartHasItems}
            onMouseLeave={onOnlineMenuClose}
          >
            <Menu isOpen={cart.length > 0 && isOnlineMenuOpen} onClose={onOnlineMenuClose}>
              <MenuButton
                as={Button}
                w="100%"
                colorScheme="blue"
                size={inputSize}
                fontSize={fontSize}
                isDisabled={cart.length === 0}
                onClick={openOnlineMenuIfCartHasItems}
              >
                Online ▼
              </MenuButton>
              <MenuList zIndex={1500} shadow="lg">
                {PH_ONLINE_PAYMENTS.map((method) => (
                  <MenuItem
                    key={method}
                    onClick={() => {
                      setPaymentMethod(method);
                      setShowPaymentModal(true);
                      onOnlineMenuClose();
                    }}
                    fontSize={fontSize}
                    fontWeight="medium"
                    color="gray.700"
                  >
                    {method}
                  </MenuItem>
                ))}
              </MenuList>
            </Menu>
          </Box>
        </HStack>
      </Box>
    </Box>
  );

  return (
    <>
      <Grid
        templateColumns={{ base: 'minmax(0, 1fr)', lg: 'minmax(0, 2fr) minmax(320px, 1fr)' }}
        gap={{ base: 3, md: 4 }}
        h={{ base: 'auto', lg: '100%' }}
        minH={0}
        w="100%"
      >
        <Box
          bg="white"
          p={{ base: 3, md: 4 }}
          borderRadius="lg"
          shadow="sm"
          h={{ base: 'auto', lg: '100%' }}
          display="flex"
          flexDir="column"
          minH={0}
          minW={0}
        >
          <Input
            placeholder="Search products or code..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            mb={3}
            size={inputSize}
            fontSize={fontSize}
            focusBorderColor="brandBlue.500"
            flexShrink={0}
          />

          <HStack
            overflowX="auto"
            pb={2}
            mb={3}
            spacing={2}
            flexShrink={0}
            sx={{
              WebkitOverflowScrolling: 'touch',
              '&::-webkit-scrollbar': { display: 'none' }
            }}
          >
            {categories.map((cat) => (
              <Badge
                key={cat}
                px={badgePx}
                py={badgePy}
                borderRadius="full"
                cursor="pointer"
                fontSize={{ base: '0.65em', md: '0.75em' }}
                colorScheme={selectedCategory === cat ? 'blue' : 'gray'}
                onClick={() => setSelectedCategory(cat)}
                whiteSpace="nowrap"
                flexShrink={0}
              >
                {cat}
              </Badge>
            ))}
          </HStack>

          <Box
            flex={1}
            minH={{ base: 'auto', lg: 0 }}
            overflowX={{ base: 'auto', lg: 'visible' }}
            overflowY={{ base: 'visible', lg: 'hidden' }}
            pb={2}
            mx={{ base: -3, md: -4, lg: 0 }}
            px={{ base: 3, md: 4, lg: 0 }}
            sx={{
              WebkitOverflowScrolling: 'touch',
              overscrollBehaviorX: 'contain',
              '&::-webkit-scrollbar': { height: '7px' },
              '&::-webkit-scrollbar-track': { bg: 'gray.50', borderRadius: 'full' },
              '&::-webkit-scrollbar-thumb': { bg: 'gray.300', borderRadius: 'full' }
            }}
          >
            <Box
              minW={{ base: '670px', md: '800px', lg: '100%' }}
              w={{ base: 'max-content', lg: '100%' }}
              h={{ base: 'auto', lg: '100%' }}
              display="flex"
              flexDir="column"
            >
              <Flex
                px={{ base: 2, md: 4 }}
                py={2}
                bg="gray.50"
                borderRadius="md"
                mb={1}
                flexShrink={0}
                align="center"
                gap={2}
              >
                <Text fontSize="xs" fontWeight="bold" color="gray.500" display="block" {...TABLE_COLUMN_PROPS.code}>
                  CODE
                </Text>
                <Text fontSize="xs" fontWeight="bold" color="gray.500" {...TABLE_COLUMN_PROPS.name}>
                  NAME
                </Text>
                <Text fontSize="xs" fontWeight="bold" color="gray.500" display="block" {...TABLE_COLUMN_PROPS.category}>
                  CATEGORY
                </Text>
                <Text fontSize="xs" fontWeight="bold" color="gray.500" textAlign="center" display="block" {...TABLE_COLUMN_PROPS.stock}>
                  STOCK
                </Text>
                <Text fontSize="xs" fontWeight="bold" color="gray.500" textAlign="right" {...TABLE_COLUMN_PROPS.price}>
                  PRICE
                </Text>
                <Text fontSize="xs" fontWeight="bold" color="gray.500" textAlign="center" {...TABLE_COLUMN_PROPS.qty}>
                  QTY
                </Text>
              </Flex>

              <VStack
                flex={1}
                minH={0}
                overflowY="auto"
                spacing={0}
                align="stretch"
                pr={1}
                sx={{
                  '&::-webkit-scrollbar': { width: '4px' },
                  '&::-webkit-scrollbar-thumb': { bg: 'gray.300', borderRadius: 'full' }
                }}
              >
                {filteredItems.length === 0 && (
                  <Text textAlign="center" color="gray.400" mt={10} fontSize={fontSize}>
                    No products found
                  </Text>
                )}

                {filteredItems.map((item) => {
                  const productKey = getProductKey(item);

                  return (
                    <ProductRow
                      key={productKey}
                      item={item}
                      currentRowQty={rowQtys[productKey] ?? ''}
                      fontSize={fontSize}
                      onAddToCart={addToCart}
                      onRowQtyChange={handleRowQtyChange}
                    />
                  );
                })}
              </VStack>
            </Box>
          </Box>
        </Box>

        {!isMobile && CartUI}
      </Grid>

      {isMobile && (
        <>
          <Box
            position="fixed"
            bottom={0}
            left={0}
            right={0}
            bg="white"
            borderTopWidth="1px"
            borderColor="gray.200"
            px={4}
            py={3}
            zIndex={1000}
            shadow="0 -4px 12px rgba(0,0,0,0.08)"
          >
            <Button
              w="100%"
              colorScheme="blue"
              size="lg"
              onClick={onCartOpen}
              borderRadius="xl"
              h="52px"
              transition="transform 120ms ease, box-shadow 120ms ease"
              _active={{ transform: 'scale(0.98)' }}
              _hover={{ transform: 'translateY(-1px)' }}
            >
              <HStack justify="space-between" w="100%">
                <HStack spacing={2}>
                  <Text fontWeight="bold" fontSize="sm">
                    {cart.length} {cart.length === 1 ? 'item' : 'items'}
                  </Text>
                </HStack>
                <Text fontWeight="black" fontSize="md">
                  &#8369;{totals.finalTotal.toFixed(2)}
                </Text>
              </HStack>
            </Button>
          </Box>

          <Box h="76px" />

          <Drawer isOpen={isCartOpen} placement="bottom" onClose={onCartClose}>
            <DrawerOverlay bg="blackAlpha.300" />
            <DrawerContent borderTopRadius="2xl" maxH="85vh" willChange="transform">
              <DrawerCloseButton top={3} right={4} />
              <DrawerHeader borderBottomWidth="1px" fontSize="md" pt={4} pb={3}>
                Current Order
                {cart.length > 0 && (
                  <Badge ml={2} colorScheme="blue" borderRadius="full" px={2}>
                    {cart.length}
                  </Badge>
                )}
              </DrawerHeader>
              <DrawerBody pb={6} px={3} overflowY="auto">
                {CartUI}
              </DrawerBody>
            </DrawerContent>
          </Drawer>
        </>
      )}

      <Modal isOpen={showPaymentModal} onClose={() => setShowPaymentModal(false)} isCentered size={{ base: 'xs', md: 'md' }}>
        <ModalOverlay backdropFilter="blur(5px)" />
        <ModalContent mx={4}>
          <ModalHeader fontSize={{ base: 'md', md: 'lg' }}>Complete {paymentMethod} Payment</ModalHeader>
          <ModalBody>
            <Text color="gray.500" mb={4} fontSize={fontSize}>
              Total Amount:{' '}
              <Text as="span" fontWeight="bold" color="brandBlue.600" fontSize={{ base: 'md', md: 'lg' }}>
                &#8369;{totals.finalTotal.toFixed(2)}
              </Text>
            </Text>
            <form id="payment-form" onSubmit={processTransaction}>
              <VStack spacing={3}>
                <Input
                  required
                  autoFocus
                  placeholder="Enter Customer Name"
                  value={customerName}
                  onChange={(e) => setCustomerName(e.target.value)}
                  size={inputSize}
                  focusBorderColor="brandBlue.500"
                />
                <Input
                  placeholder="Enter Address (Optional)"
                  value={customerAddress}
                  onChange={(e) => setCustomerAddress(e.target.value)}
                  size={inputSize}
                  focusBorderColor="brandBlue.500"
                />
              </VStack>
            </form>
          </ModalBody>
          <ModalFooter gap={2}>
            <Button variant="ghost" onClick={() => setShowPaymentModal(false)} isDisabled={isProcessing} size={inputSize}>
              Cancel
            </Button>
            <Button colorScheme="blue" form="payment-form" type="submit" isLoading={isProcessing} size={inputSize}>
              Confirm Order
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>

      <Modal isOpen={!!receiptData} onClose={() => setReceiptData(null)} isCentered size={{ base: 'xs', md: 'md' }}>
        <ModalOverlay backdropFilter="blur(5px)" />
        <ModalContent mx={4} textAlign="center" py={4}>
          <ModalBody>
            <Text fontSize={{ base: '4xl', md: '5xl' }} mb={2}>
              OK
            </Text>
            <Text fontSize={{ base: 'xl', md: '2xl' }} fontWeight="bold">
              Payment Successful!
            </Text>
            <Text color="gray.500" mt={2} fontSize={fontSize}>
              Order saved for <strong>{receiptData?.customerName}</strong>
            </Text>

            {receiptData && (
              <Box mt={4} bg="gray.50" borderRadius="lg" p={3} textAlign="left">
                <Text fontSize="xs" fontWeight="bold" color="gray.500" mb={2}>
                  ORDER SUMMARY
                </Text>
                {receiptData.items.map((item, i) => (
                  <Flex key={`${item.itemId}-${i}`} justify="space-between" fontSize="xs" color="gray.600" mb={1} gap={2}>
                    <Box flex={1} minW={0}>
                      <Text noOfLines={1}>
                        {item.qty}x {item.name}
                      </Text>
                      {item.code && (
                        <Text color="gray.400" noOfLines={1}>
                          Code: {item.code}
                        </Text>
                      )}
                    </Box>
                    <Text flexShrink={0}>&#8369;{(item.price * item.qty).toFixed(2)}</Text>
                  </Flex>
                ))}
                <Divider my={2} />
                <Flex justify="space-between" fontSize="sm" fontWeight="bold">
                  <Text>Total Paid</Text>
                  <Text color="brandBlue.600">&#8369;{receiptData.finalTotal.toFixed(2)}</Text>
                </Flex>
              </Box>
            )}

            <HStack justify="center" mt={5} spacing={3}>
              <Button variant="outline" size={inputSize} onClick={() => setReceiptData(null)}>
                New Order
              </Button>
              <Button colorScheme="blue" size={inputSize} onClick={printPurchaseOrder}>
                Print P.O.
              </Button>
            </HStack>
          </ModalBody>
        </ModalContent>
      </Modal>
    </>
  );  
}
