import CryptoJS from 'crypto-js';

const SECRET_KEY = 'my-super-secret-inventory-key'; 

export const encryptData = (data) => {
  if (data === undefined || data === null || data === '') return data;
  return CryptoJS.AES.encrypt(data.toString(), SECRET_KEY).toString();
};

export const decryptData = (ciphertext) => {
  if (ciphertext === undefined || ciphertext === null || ciphertext === '') return ciphertext;
  
  if (!ciphertext.toString().startsWith('U2FsdGVkX1')) {
    return ciphertext;
  }

  try {
    const bytes = CryptoJS.AES.decrypt(ciphertext.toString(), SECRET_KEY);
    const decrypted = bytes.toString(CryptoJS.enc.Utf8);
    return decrypted || ciphertext; 
  } catch (e) {
    console.error("Decryption failed", e);
    return ciphertext;
  }
};