import React, { useState } from 'react';
import {
  Box,
  Flex,
  Input,
  Button,
  FormControl,
  FormLabel,
  useToast,
  Text,
  VStack,
  Image
} from '@chakra-ui/react';
import {
  sendPasswordResetEmail,
  signInWithEmailAndPassword
} from 'firebase/auth';
import { auth } from './firebaseConfig';
import {
  getEmailFromLoginIdentifier,
  sendPasswordResetEmailFallback
} from './dbStaffAuth';

const brandBlue = '#1E3F82';
const brandGreen = '#88B24E';
const brandSky = '#21A6DF';

const getFriendlyAuthError = (error) => {
  const messages = {
    'auth/invalid-credential': 'Incorrect email or password.',
    'auth/user-not-found': 'No user found with this email.',
    'auth/wrong-password': 'Incorrect email or password.',
    'auth/invalid-email': 'Enter a valid email address.',
    'auth/email-already-in-use': 'This email already exists.',
    'auth/weak-password': 'Password must be at least 6 characters.',
    'auth/too-many-requests': 'Too many attempts. Try again later.',
    'auth/network-request-failed': 'Network error. Check your connection.',
    'permission-denied': 'Firestore blocked username lookup before login. Allow public username lookup or sign in with email.'
  };

  return messages[error?.code] || error?.message || 'Firebase Auth failed.';
};

const sendPasswordResetWithFallback = async (email) => {
  try {
    await sendPasswordResetEmail(auth, email);
  } catch {
    await sendPasswordResetEmailFallback(email);
  }
};

export default function Login() {
  const [loginId, setLoginId] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const toast = useToast();

  const handleLogin = async (e) => {
    e.preventDefault();

    if (!loginId.trim() || !password) {
      toast({
        title: 'Login failed',
        description: !loginId.trim() ? 'Enter your username or email.' : 'Enter your password.',
        status: 'error',
        duration: 3000,
        position: 'top'
      });
      return;
    }

    setIsLoading(true);

    try {
      const resolvedEmail = await getEmailFromLoginIdentifier(loginId);
      await signInWithEmailAndPassword(auth, resolvedEmail, password);
    } catch (error) {
      toast({
        title: 'Login failed',
        description: getFriendlyAuthError(error),
        status: 'error',
        duration: 3000,
        position: 'top'
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetPassword = async () => {
    if (!loginId.trim()) {
      toast({
        title: 'Username or email required',
        description: 'Enter your username or email first.',
        status: 'error',
        position: 'top'
      });
      return;
    }

    setIsResetting(true);

    try {
      const resolvedEmail = await getEmailFromLoginIdentifier(loginId);
      await sendPasswordResetWithFallback(resolvedEmail);

      toast({
        title: 'Password reset sent',
        description: `Check ${resolvedEmail}.`,
        status: 'success',
        duration: 4000,
        position: 'top'
      });
    } catch (error) {
      toast({
        title: 'Reset failed',
        description: getFriendlyAuthError(error),
        status: 'error',
        duration: 4000,
        position: 'top'
      });
    } finally {
      setIsResetting(false);
    }
  };

  return (
    <Flex
      minH="100vh"
      align="center"
      justify="center"
      bg="#F7FAFC"
      px={4}
      py={8}
    >
      <Box
        w="100%"
        maxW="430px"
        bg="white"
        borderRadius="xl"
        borderWidth="1px"
        borderColor="blue.50"
        shadow="0 18px 45px rgba(30, 63, 130, 0.12)"
        overflow="hidden"
      >
        <Box
          h="4px"
          bgGradient={`linear(to-r, ${brandBlue}, ${brandSky}, ${brandGreen})`}
        />

        <Box px={{ base: 6, md: 8 }} py={{ base: 7, md: 8 }}>
          <VStack spacing={5} align="stretch">
            <Box textAlign="center">
              <Flex
                w="96px"
                h="96px"
                mx="auto"
                mb={5}
                borderRadius="2xl"
                align="center"
                justify="center"
                shadow="0 16px 30px rgba(30, 63, 130, 0.18)"
                bg="white"
                borderWidth="1px"
                borderColor="gray.100"
                overflow="hidden"
              >
                <Image
                  src="/logo.jpg"
                  alt="Medident Care logo"
                  w="100%"
                  h="100%"
                  objectFit="cover"
                />
              </Flex>

              {/* <Text color="gray.500" fontSize="sm">
                Sign in with your staff username and password
              </Text> */}
            </Box>

            <form onSubmit={handleLogin}>
              <VStack spacing={4} align="stretch">
                <FormControl isRequired>
                  <FormLabel fontSize="sm" color="gray.600" fontWeight="semibold">
                    Username
                  </FormLabel>
                  <Input
                    value={loginId}
                    onChange={(e) => setLoginId(e.target.value)}
                    autoCapitalize="none"
                    autoComplete="username"
                    placeholder="Username or email"
                    bg="gray.50"
                    borderColor="gray.100"
                    borderRadius="md"
                    focusBorderColor={brandSky}
                    _hover={{ borderColor: 'gray.200' }}
                  />
                </FormControl>

                <FormControl isRequired>
                  <FormLabel fontSize="sm" color="gray.600" fontWeight="semibold">
                    Password
                  </FormLabel>
                  <Input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    autoComplete="current-password"
                    bg="gray.50"
                    borderColor="gray.100"
                    borderRadius="md"
                    focusBorderColor={brandSky}
                    _hover={{ borderColor: 'gray.200' }}
                  />
                </FormControl>

                <Button
                  type="submit"
                  w="100%"
                  size="lg"
                  mt={2}
                  bg={brandBlue}
                  color="white"
                  borderRadius="md"
                  isLoading={isLoading}
                  _hover={{ bg: brandSky }}
                  _active={{ bg: brandBlue }}
                >
                  Sign In
                </Button>

                {/* <Button
                  type="button"
                  variant="ghost"
                  color={brandBlue}
                  isLoading={isResetting}
                  onClick={handleResetPassword}
                >
                  Forgot password?
                </Button> */}
              </VStack>
            </form>

            <Flex justify="center" align="center" gap={2}>
              <Box w="7px" h="7px" borderRadius="full" bg={brandGreen} />
              <Text fontSize="xs" color="gray.400" fontWeight="medium">
                Authorized personnel only
              </Text>
            </Flex>
          </VStack>
        </Box>
      </Box>
    </Flex>
  );
}
