const getCurrentMonth = () => {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  return `${year}-${month}`;
};

const getCurrentWeek = () => {
  const now = new Date();
  const date = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const day = date.getDay() || 7;

  date.setDate(date.getDate() + 4 - day);

  const yearStart = new Date(date.getFullYear(), 0, 1);
  const week = Math.ceil((((date - yearStart) / 86400000) + 1) / 7);

  return `${date.getFullYear()}-W${String(week).padStart(2, '0')}`;
};

const getWeekRange = (weekStr) => {
  if (!weekStr) return { start: null, end: null };
  const [yearStr, weekPart] = weekStr.split('-W');
  const year = parseInt(yearStr, 10);
  const week = parseInt(weekPart, 10);
  const jan4 = new Date(year, 0, 4);
  const dayOfWeek = jan4.getDay() || 7;
  const monday = new Date(jan4);
  monday.setDate(jan4.getDate() - (dayOfWeek - 1) + (week - 1) * 7);
  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);
  sunday.setHours(23, 59, 59, 999);
  return { start: monday, end: sunday };
};

const codeSortCollator = new Intl.Collator(undefined, {
  numeric: true,
  sensitivity: 'base'
});

const getProductDisplayLabel = (item) => {
  if (!item) return '';
  const code = String(item.code || '').trim();
  const name = String(item.name || '').trim();
  return code ? `${code} - ${name}` : name;
};

const sortProductsByCode = (a, b) => {
  const codeA = String(a.code || '').trim();
  const codeB = String(b.code || '').trim();

  if (codeA && codeB) {
    const codeCompare = codeSortCollator.compare(codeA, codeB);
    if (codeCompare !== 0) return codeCompare;
  } else if (codeA) {
    return -1;
  } else if (codeB) {
    return 1;
  }

  return codeSortCollator.compare(String(a.name || ''), String(b.name || ''));
};

