const formatReportAmount = (value) => {
  const numberValue = Number(value || 0);
  return Number.isFinite(numberValue) ? numberValue.toFixed(2) : '0.00';
};

const roundUpReportAmount = (value) => Math.ceil((Number(value || 0) - Number.EPSILON) * 100) / 100;

const createReportRowId = (prefix) =>
  `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

const formatReportDate = (monthStr) => {
  const [year, month] = String(monthStr || '').split('-').map(Number);
  const date = year && month ? new Date(year, month, 0) : new Date();
  const day = String(date.getDate()).padStart(2, '0');
  const monthName = date.toLocaleString('en-US', { month: 'short' });
  return `${day}-${monthName}-${date.getFullYear()}`;
};

const formatReportSeries = () => 'ISSIPF000009407091';

const parseReportAmount = (value) => {
  const cleanedValue = String(value || '').replace(/[^\d.-]/g, '');
  const numberValue = Number(cleanedValue);
  return Number.isFinite(numberValue) ? numberValue : 0;
};

const buildReportTotals = (rows, discountValue = 0) => {
  const subtotal = rows.reduce((sum, row) => sum + parseReportAmount(row.amount), 0);
  const discount = parseReportAmount(discountValue);
  const vatableSales = Math.max(subtotal - discount, 0);
  const vatAmount = roundUpReportAmount(vatableSales * REPORT_VAT_RATE);
  const total = vatableSales + vatAmount;

  return {
    subtotal: formatReportAmount(subtotal),
    discount: formatReportAmount(discount),
    vatableSales: formatReportAmount(vatableSales),
    exemptSales: '0.00',
    zeroSales: '0.00',
    totalSalesAmount: formatReportAmount(vatableSales),
    vat: formatReportAmount(vatAmount),
    total: formatReportAmount(total)
  };
};

