import React, { useState, useEffect, useMemo } from 'react';
import { db } from './firebaseConfig';
import { collection, addDoc, doc, deleteDoc, updateDoc, onSnapshot, writeBatch } from 'firebase/firestore';
import * as XLSX from 'xlsx';
import { encryptData, decryptData } from './encryption';
import {
  Box,
  Flex,
  Input,
  Button,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  TableContainer,
  Badge,
  Heading,
  Text,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  useToast,
  FormControl,
  FormLabel,
  SimpleGrid,
  InputGroup,
  InputLeftElement,
  VStack,
  HStack,
  useBreakpointValue,
  Tabs,
  TabList,
  Tab
} from '@chakra-ui/react';

const safePrice = (v) => {
  if (v === undefined || v === null) return 0;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace(/[^\d.-]/g, ''));
  return Number.isNaN(n) ? 0 : n;
};

const normalizeProductCode = (value) => String(value || '').trim().toLowerCase();

const getRowValue = (row, keys) => {
  const normalizedKeys = keys.map((key) => key.toLowerCase());
  const foundEntry = Object.entries(row).find(([rowKey, value]) =>
    normalizedKeys.includes(String(rowKey).trim().toLowerCase()) &&
    value !== undefined &&
    value !== null
  );
  return foundEntry ? foundEntry[1] : '';
};

const hasRowValue = (row, keys) => String(getRowValue(row, keys)).trim() !== '';

const excelColumnHelp = 'Code (unique ID), Name, Supplier, Category, Stock, Purchase Price, Price, Qty';
const codeSortCollator = new Intl.Collator(undefined, {
  numeric: true,
  sensitivity: 'base'
});

const sortProductsByCode = (a, b) => {
  const codeA = String(a.code || '').trim();
  const codeB = String(b.code || '').trim();

  if (codeA && codeB) {
    const codeCompare = codeSortCollator.compare(codeA, codeB);
    if (codeCompare !== 0) return codeCompare;
  } else if (codeA) {
    return -1;
  } else if (codeB) {
    return 1;
  }

  return codeSortCollator.compare(String(a.name || ''), String(b.name || ''));
};

const encryptItemObject = (itemObj) => ({
  code: encryptData(itemObj.code),
  codeLower: encryptData(itemObj.codeLower),
  name: encryptData(itemObj.name),
  nameLower: encryptData(itemObj.nameLower),
  supplierName: encryptData(itemObj.supplierName),
  supplierNameLower: encryptData(itemObj.supplierNameLower),
  category: encryptData(itemObj.category),
  categoryLower: encryptData(itemObj.categoryLower),
  purchasePrice: encryptData(itemObj.purchasePrice.toString()),
  price: encryptData(itemObj.price.toString()),
  stock: encryptData(itemObj.stock.toString()),
  isActive: itemObj.isActive
});

export default function Inventory() {
  const [items, setItems] = useState([]);
  const [code, setCode] = useState('');
  const [name, setName] = useState('');
  const [supplierName, setSupplierName] = useState('');
  const [category, setCategory] = useState('');
  const [purchasePrice, setPurchasePrice] = useState('');
  const [price, setPrice] = useState('');
  const [stock, setStock] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [editCode, setEditCode] = useState('');
  const [editName, setEditName] = useState('');
  const [editSupplierName, setEditSupplierName] = useState('');
  const [editCategory, setEditCategory] = useState('');
  const [editPurchasePrice, setEditPurchasePrice] = useState('');
  const [editPrice, setEditPrice] = useState('');
  const [editStock, setEditStock] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isDeletingAll, setIsDeletingAll] = useState(false);
  
  const [activeTab, setActiveTab] = useState('all');

  const toast = useToast();
  const itemsCollectionRef = collection(db, 'inventory');

  const isMobile = useBreakpointValue({ base: true, md: false });
  const inputSize = useBreakpointValue({ base: 'sm', md: 'md' });

  useEffect(() => {
    const unsubscribe = onSnapshot(itemsCollectionRef, (snapshot) => {
      setItems(snapshot.docs.map((docSnap) => {
        const data = docSnap.data();
        return {
          id: docSnap.id,
          code: decryptData(data.code),
          codeLower: decryptData(data.codeLower),
          name: decryptData(data.name),
          nameLower: decryptData(data.nameLower),
          supplierName: decryptData(data.supplierName),
          supplierNameLower: decryptData(data.supplierNameLower),
          category: decryptData(data.category),
          categoryLower: decryptData(data.categoryLower),
          purchasePrice: Number(decryptData(data.purchasePrice)) || 0,
          price: Number(decryptData(data.price)) || 0,
          stock: Number(decryptData(data.stock)) || 0,
          isActive: data.isActive
        };
      }));
    });
    return () => unsubscribe();
  }, []);

  const buildItemData = ({ itemCode, itemName, itemSupplierName, itemCategory, itemPurchasePrice, itemPrice, itemStock }) => {
    const cleanCode = String(itemCode || '').trim();
    const cleanName = String(itemName || '').trim();
    const cleanSupplierName = String(itemSupplierName || '').trim();
    const cleanCategory = String(itemCategory || '').trim() || 'General';

    return {
      code: cleanCode,
      codeLower: normalizeProductCode(cleanCode),
      name: cleanName,
      nameLower: cleanName.toLowerCase(),
      supplierName: cleanSupplierName,
      supplierNameLower: cleanSupplierName.toLowerCase(),
      category: cleanCategory,
      categoryLower: cleanCategory.toLowerCase(),
      purchasePrice: safePrice(itemPurchasePrice),
      price: safePrice(itemPrice),
      stock: parseInt(itemStock, 10) || 0,
      isActive: true
    };
  };

  const validateItemData = (itemData, currentId = null) => {
    if (!itemData.code) {
      toast({ title: 'Product code is required', description: 'Code is the unique product ID.', status: 'error', position: 'top' });
      return false;
    }

    if (!itemData.name) {
      toast({ title: 'Product name is required', status: 'error', position: 'top' });
      return false;
    }

    const duplicate = items.find(
      (item) => item.id !== currentId && normalizeProductCode(item.code) === itemData.codeLower
    );

    if (duplicate) {
      toast({
        title: 'Product code already exists',
        description: `"${itemData.code}" is already used by "${duplicate.name}".`,
        status: 'error',
        duration: 3000,
        position: 'top'
      });
      return false;
    }

    return true;
  };

  const addItem = async (e) => {
    e.preventDefault();
    try {
      const itemData = buildItemData({
        itemCode: code,
        itemName: name,
        itemSupplierName: supplierName,
        itemCategory: category,
        itemPurchasePrice: purchasePrice,
        itemPrice: price,
        itemStock: stock
      });

      const existing = items.find((item) => normalizeProductCode(item.code) === itemData.codeLower);

      if (!validateItemData(itemData, existing?.id || null)) return;

      const encryptedData = encryptItemObject(itemData);

      if (existing) {
        await updateDoc(doc(db, 'inventory', existing.id), encryptedData);
        toast({ title: 'Updated product with same code', status: 'info', duration: 2000, position: 'top' });
      } else {
        await addDoc(itemsCollectionRef, encryptedData);
        toast({ title: 'Product Added', status: 'success', duration: 2000, position: 'top' });
      }

      setCode('');
      setName('');
      setSupplierName('');
      setCategory('');
      setPurchasePrice('');
      setPrice('');
      setStock('');
    } catch (error) {
      toast({ title: 'Error', description: error.message, status: 'error', position: 'top' });
    }
  };

  const deleteItem = async (id) => {
    if (window.confirm('Delete this item?')) {
      try {
        await deleteDoc(doc(db, 'inventory', id));
        toast({ title: 'Product deleted', status: 'success', duration: 2000, position: 'top' });
      } catch (err) {
        toast({ title: 'Error deleting', description: err.message, status: 'error' });
      }
    }
  };

  const deleteAllProducts = async () => {
    if (items.length === 0) {
      toast({ title: 'No products to delete', status: 'info', duration: 2000, position: 'top' });
      return;
    }

    const firstConfirm = window.confirm(
      `Delete ALL ${items.length} products?\n\nThis cannot be undone. Sales records will not be deleted.`
    );
    if (!firstConfirm) return;

    const typedConfirm = window.prompt('Type DELETE ALL to confirm deleting every inventory product.');
    if (typedConfirm !== 'DELETE ALL') {
      toast({ title: 'Delete all cancelled', status: 'info', duration: 2000, position: 'top' });
      return;
    }

    setIsDeletingAll(true);

    try {
      const batches = [];
      let currentBatch = writeBatch(db);
      let opCount = 0;

      items.forEach((item) => {
        currentBatch.delete(doc(db, 'inventory', item.id));
        opCount += 1;

        if (opCount === 490) {
          batches.push(currentBatch);
          currentBatch = writeBatch(db);
          opCount = 0;
        }
      });

      if (opCount > 0) batches.push(currentBatch);
      for (const batch of batches) await batch.commit();

      toast({
        title: 'All products deleted',
        description: `${items.length} product${items.length === 1 ? '' : 's'} removed from inventory.`,
        status: 'success',
        duration: 3000,
        position: 'top'
      });
    } catch (error) {
      toast({ title: 'Error deleting products', description: error.message, status: 'error', position: 'top' });
    } finally {
      setIsDeletingAll(false);
    }
  };

  const openEdit = (item) => {
    setEditId(item.id);
    setEditCode(item.code || '');
    setEditName(item.name || '');
    setEditSupplierName(item.supplierName || '');
    setEditCategory(item.category || 'General');
    setEditPurchasePrice(item.purchasePrice || '');
    setEditPrice(item.price || '');
    setEditStock(item.stock || 0);
    setIsEditing(true);
  };

  const updateItem = async (e) => {
    e.preventDefault();
    try {
      const itemData = buildItemData({
        itemCode: editCode,
        itemName: editName,
        itemSupplierName: editSupplierName,
        itemCategory: editCategory,
        itemPurchasePrice: editPurchasePrice,
        itemPrice: editPrice,
        itemStock: editStock
      });

      if (!validateItemData(itemData, editId)) return;

      const encryptedData = encryptItemObject(itemData);
      await updateDoc(doc(db, 'inventory', editId), encryptedData);
      
      setIsEditing(false);
      setEditId(null);
      toast({ title: 'Product Updated', status: 'success', duration: 2000, position: 'top' });
    } catch (error) {
      toast({ title: 'Error', description: error.message, status: 'error', position: 'top' });
    }
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setIsUploading(true);
    const reader = new FileReader();

    reader.onload = async (evt) => {
      try {
        const buffer = evt.target.result;
        const workbook = XLSX.read(buffer, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const data = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName]);

        const codeDict = {};
        items.forEach((item) => {
          const existingCode = normalizeProductCode(item.code);
          if (existingCode) codeDict[existingCode] = item.id;
        });

        const rowsByCode = new Map();
        const skippedRows = [];
        const duplicateRows = [];

        data.forEach((row, index) => {
          const rowCode = getRowValue(row, ['Code', 'Product Code', 'SKU', 'Item Code']);
          const rowName = getRowValue(row, ['Name', 'Item Name', 'Product Name']);
          const rowSupplierName = getRowValue(row, ['Supplier', 'Supplier Name', 'Vendor']);
          const rowCategory = getRowValue(row, ['Category']);
          const rowPurchasePrice = getRowValue(row, ['Purchase Price', 'Cost', 'Cost Price']);
          const rowPrice = getRowValue(row, ['Price', 'Unit Price', 'Selling Price']);
          const rowStock = getRowValue(row, ['Stock']);
          const rowQty = getRowValue(row, ['Qty', 'Quantity']);
          const stockValue = hasRowValue(row, ['Stock']) ? rowStock : rowQty;
          
          const hasRequiredColumns =
            hasRowValue(row, ['Code', 'Product Code', 'SKU', 'Item Code']) &&
            hasRowValue(row, ['Name', 'Item Name', 'Product Name']) &&
            hasRowValue(row, ['Supplier', 'Supplier Name', 'Vendor']) &&
            hasRowValue(row, ['Category']) &&
            (hasRowValue(row, ['Price', 'Unit Price']) || hasRowValue(row, ['Purchase Price', 'Cost'])) &&
            (hasRowValue(row, ['Stock']) || hasRowValue(row, ['Qty', 'Quantity']));

          if (!hasRequiredColumns) {
            skippedRows.push(index + 2);
            return;
          }

          const itemData = buildItemData({
            itemCode: rowCode,
            itemName: rowName,
            itemSupplierName: rowSupplierName,
            itemCategory: rowCategory,
            itemPurchasePrice: rowPurchasePrice,
            itemPrice: rowPrice,
            itemStock: stockValue
          });

          if (!itemData.code || !itemData.name) {
            skippedRows.push(index + 2);
            return;
          }

          if (rowsByCode.has(itemData.codeLower)) {
            duplicateRows.push(index + 2);
          }

          rowsByCode.set(itemData.codeLower, itemData);
        });

        if (rowsByCode.size === 0) {
          toast({
            title: 'No rows uploaded',
            description: `Required Excel columns: ${excelColumnHelp}. Code is the unique ID. Stock is used first; Qty is accepted if Stock is blank.`,
            status: 'error',
            duration: 5000,
            position: 'top'
          });
          return;
        }

        const batches = [];
        let currentBatch = writeBatch(db);
        let opCount = 0;

        rowsByCode.forEach((itemData) => {
          const existingId = codeDict[itemData.codeLower];
          const encryptedData = encryptItemObject(itemData);

          if (existingId) {
            currentBatch.set(doc(db, 'inventory', existingId), encryptedData, { merge: true });
          } else {
            const newRef = doc(itemsCollectionRef);
            currentBatch.set(newRef, encryptedData);
            codeDict[itemData.codeLower] = newRef.id;
          }

          opCount += 1;
          if (opCount === 490) {
            batches.push(currentBatch);
            currentBatch = writeBatch(db);
            opCount = 0;
          }
        });

        if (opCount > 0) batches.push(currentBatch);
        for (const batch of batches) await batch.commit();

        const warnings = [];
        if (skippedRows.length) {
          warnings.push(`Skipped row(s): ${skippedRows.slice(0, 8).join(', ')}${skippedRows.length > 8 ? '...' : ''}.`);
        }
        if (duplicateRows.length) {
          warnings.push(`Duplicate code row(s): ${duplicateRows.slice(0, 8).join(', ')}${duplicateRows.length > 8 ? '...' : ''}; last matching code was used.`);
        }

        toast({
          title: warnings.length ? 'Upload Complete with warnings' : 'Upload Complete',
          description: warnings.length ? warnings.join(' ') : 'Products with matching codes were updated; new codes were added.',
          status: warnings.length ? 'warning' : 'success',
          duration: 5000,
          position: 'top'
        });
      } catch (err) {
        toast({
          title: 'Upload Failed. Check columns.',
          description: `Required Excel columns: ${excelColumnHelp}. Code is the unique ID. Stock is used first; Qty is accepted if Stock is blank.`,
          status: 'error',
          duration: 5000,
          position: 'top'
        });
      } finally {
        setIsUploading(false);
        e.target.value = null;
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const lowStockTotalCount = useMemo(() => items.filter((i) => i.stock <= 5).length, [items]);

  const searchedItems = useMemo(() => {
    const search = (searchTerm || '').trim().toLowerCase();
    let result = items;
    
    if (search) {
      result = result.filter((i) =>
        (i.nameLower || '').includes(search) ||
        (i.codeLower || '').includes(search) ||
        (i.supplierNameLower || '').includes(search) ||
        (i.categoryLower || '').includes(search)
      );
    }
    
    return [...result].sort(sortProductsByCode);
  }, [items, searchTerm]);

  const desktopRows = useMemo(() => {
    return searchedItems.map((item) => (
      <Tr 
        key={item.id} 
        className={item.stock > 5 ? 'normal-stock-row' : 'low-stock-row'}
        _hover={{ bg: 'gray.50' }} 
        bg={item.stock <= 0 ? 'red.100' : item.stock <= 5 ? 'red.50' : 'white'}
      >
        <Td>
          {item.code ? (
            <Badge colorScheme="blue" variant="subtle">{item.code}</Badge>
          ) : (
            <Text color="gray.400" fontSize="xs">-</Text>
          )}
        </Td>
        <Td>
          <Text fontWeight="bold" fontSize="sm" noOfLines={1}>{item.name}</Text>
          <VStack display={{ base: 'flex', lg: 'none' }} align="start" spacing={0} mt={1}>
            {item.supplierName && <Text fontSize="xs" color="gray.500">Supplier: {item.supplierName}</Text>}
            <Badge colorScheme="teal" fontSize="0.6em" display={{ base: 'inline-flex', md: 'none' }}>
              {item.category || 'General'}
            </Badge>
          </VStack>
        </Td>
        <Td display={{ base: 'none', lg: 'table-cell' }}>
          <Text fontSize="sm" color="gray.600" noOfLines={1}>{item.supplierName || '-'}</Text>
        </Td>
        <Td display={{ base: 'none', md: 'table-cell' }}>
          <Badge colorScheme="teal">{item.category || 'General'}</Badge>
        </Td>
        <Td>
          <Badge colorScheme={item.stock <= 5 ? 'red' : 'green'} variant={item.stock <= 5 ? 'solid' : 'subtle'}>
            {item.stock <= 0 ? 'Out' : item.stock}
          </Badge>
        </Td>
        <Td fontWeight="semibold" color="gray.600">&#8369;{safePrice(item.purchasePrice).toFixed(2)}</Td>
        <Td fontWeight="semibold" color="blue.600">&#8369;{safePrice(item.price).toFixed(2)}</Td>
        <Td>
          <HStack spacing={1}>
            <Button size="xs" colorScheme="blue" variant="ghost" onClick={() => openEdit(item)}>Edit</Button>
            <Button size="xs" colorScheme="red" variant="ghost" onClick={() => deleteItem(item.id)}>Del</Button>
          </HStack>
        </Td>
      </Tr>
    ));
  }, [searchedItems]);

  const mobileRows = useMemo(() => {
    return searchedItems.map((item) => (
      <Box
        key={item.id}
        className={item.stock > 5 ? 'normal-stock-row' : 'low-stock-row'}
        p={3}
        bg={item.stock <= 0 ? 'red.100' : item.stock <= 5 ? 'red.50' : 'white'}
        borderWidth="1px"
        borderColor="gray.200"
        borderRadius="lg"
        shadow="sm"
      >
        <Flex justify="space-between" align="flex-start" mb={2}>
          <Box flex={1} minW={0}>
            <HStack spacing={1} mb={1} flexWrap="wrap">
              {item.code && <Badge colorScheme="blue" variant="subtle">{item.code}</Badge>}
              <Badge colorScheme="teal" fontSize="0.6em">{item.category || 'General'}</Badge>
            </HStack>
            <Text fontWeight="bold" fontSize="sm" noOfLines={2}>{item.name}</Text>
            {item.supplierName && (
              <Text fontSize="xs" color="gray.500" noOfLines={1} mt={1}>
                Supplier: {item.supplierName}
              </Text>
            )}
          </Box>
          <Badge
            ml={2}
            colorScheme={item.stock <= 5 ? 'red' : 'green'}
            variant={item.stock <= 5 ? 'solid' : 'subtle'}
            flexShrink={0}
          >
            {item.stock <= 0 ? 'Out of Stock' : `${item.stock} in stock`}
          </Badge>
        </Flex>

        <Flex justify="space-between" align="flex-end" mt={2}>
          <Box>
            <Text fontSize="xs" color="gray.500" mb={1}>Cost: &#8369;{safePrice(item.purchasePrice).toFixed(2)}</Text>
            <Text fontWeight="bold" fontSize="md" color="medicalBlue.600">Sell: &#8369;{safePrice(item.price).toFixed(2)}</Text>
          </Box>
          <HStack spacing={2}>
            <Button size="xs" colorScheme="blue" onClick={() => openEdit(item)}>Edit</Button>
            <Button size="xs" colorScheme="red" variant="outline" onClick={() => deleteItem(item.id)}>Delete</Button>
          </HStack>
        </Flex>
      </Box>
    ));
  }, [searchedItems]);

  const displayedCount = useMemo(() => {
    if (activeTab === 'all') return searchedItems.length;
    return searchedItems.filter(i => i.stock <= 5).length;
  }, [searchedItems, activeTab]);

  return (
    <Flex h={{ base: 'auto', lg: '100%' }} direction="column" gap={4} minH={0} p={{ base: 3, md: 4 }}>
      <Box bg="white" p={{ base: 3, md: 4 }} borderRadius="lg" shadow="sm" flexShrink={0}>
        <Heading size="sm" mb={3}>Add New Product</Heading>

        <form onSubmit={addItem}>
          <Flex gap={2} align="flex-end" wrap="wrap">
            <FormControl flex={{ base: '1 1 100%', md: '1 1 120px' }} minW={{ base: '100%', md: '120px' }} isRequired>
              <FormLabel fontSize="xs" mb={1} color="gray.500" fontWeight="semibold">CODE / ID</FormLabel>
              <Input size={inputSize} placeholder="Unique code" value={code} onChange={(e) => setCode(e.target.value)} />
            </FormControl>

            <FormControl flex={{ base: '1 1 100%', md: '2 1 180px' }} minW={{ base: '100%', md: '180px' }}>
              <FormLabel fontSize="xs" mb={1} color="gray.500" fontWeight="semibold">ITEM NAME</FormLabel>
              <Input size={inputSize} placeholder="Product name" required value={name} onChange={(e) => setName(e.target.value)} />
            </FormControl>

            <FormControl flex={{ base: '1 1 100%', sm: '1 1 160px' }} minW={{ base: '100%', sm: '160px' }}>
              <FormLabel fontSize="xs" mb={1} color="gray.500" fontWeight="semibold">SUPPLIER NAME</FormLabel>
              <Input size={inputSize} placeholder="Supplier name" value={supplierName} onChange={(e) => setSupplierName(e.target.value)} />
            </FormControl>

            <FormControl flex={{ base: '1 1 100%', sm: '1 1 140px' }} minW={{ base: '100%', sm: '140px' }}>
              <FormLabel fontSize="xs" mb={1} color="gray.500" fontWeight="semibold">CATEGORY</FormLabel>
              <Input size={inputSize} placeholder="Category" required value={category} onChange={(e) => setCategory(e.target.value)} />
            </FormControl>

            <FormControl flex={{ base: '1 1 calc(33% - 8px)', sm: '1 1 80px' }} minW={{ base: 'calc(33% - 8px)', sm: '80px' }}>
              <FormLabel fontSize="xs" mb={1} color="gray.500" fontWeight="semibold">STOCK</FormLabel>
              <Input size={inputSize} type="number" min="0" placeholder="0" required value={stock} onChange={(e) => setStock(e.target.value)} />
            </FormControl>

            <FormControl flex={{ base: '1 1 calc(33% - 8px)', sm: '1 1 110px' }} minW={{ base: 'calc(33% - 8px)', sm: '110px' }}>
              <FormLabel fontSize="xs" mb={1} color="gray.500" fontWeight="semibold">PURCHASE (&#8369;)</FormLabel>
              <Input size={inputSize} type="number" step="0.01" min="0" placeholder="0.00" required value={purchasePrice} onChange={(e) => setPurchasePrice(e.target.value)} />
            </FormControl>

            <FormControl flex={{ base: '1 1 calc(33% - 8px)', sm: '1 1 110px' }} minW={{ base: 'calc(33% - 8px)', sm: '110px' }}>
              <FormLabel fontSize="xs" mb={1} color="gray.500" fontWeight="semibold">SELLING (&#8369;)</FormLabel>
              <Input size={inputSize} type="number" step="0.01" min="0" placeholder="0.00" required value={price} onChange={(e) => setPrice(e.target.value)} />
            </FormControl>

            <Button size={inputSize} colorScheme="teal" type="submit" px={6} flexShrink={0} w={{ base: '100%', sm: 'auto' }}>
              Add Product
            </Button>
          </Flex>
        </form>

        <Flex mt={4} p={3} bg="blue.50" border="1px dashed" borderColor="blue.200" borderRadius="md" align="center" justify="space-between" flexWrap="wrap" gap={3}>
          <Box flex={1} minW={{ base: '100%', sm: '200px' }}>
            <Text fontWeight="bold" fontSize="sm" color="medicalBlue.700">Bulk Upload via Excel</Text>
            <Text fontSize="xs" color="gray.600">
              Excel columns: <strong>Code, Name, Supplier, Category, Stock, Purchase Price, Price, Qty</strong>. Code is the unique ID. Same code updates the product; new code adds a product.
            </Text>
          </Box>
          <Input type="file" size="sm" accept=".xlsx, .xls, .csv" onChange={handleFileUpload} disabled={isUploading} w={{ base: '100%', sm: 'auto' }} bg="white" p={1} />
        </Flex>
      </Box>

      <Box bg="white" p={{ base: 3, md: 4 }} borderRadius="lg" shadow="sm" flex={1} display="flex" flexDir="column" minH={0}>
        <Flex justify="space-between" align={{ base: 'flex-start', lg: 'center' }} mb={3} flexShrink={0} gap={3} direction={{ base: 'column', lg: 'row' }}>
          
          <Tabs 
            variant="unstyled" 
            size="sm" 
            onChange={(index) => setActiveTab(index === 0 ? 'all' : 'low')} 
            index={activeTab === 'all' ? 0 : 1} 
            flexShrink={0}
            sx={{ '& *': { transition: 'none !important' } }}
          >
            <TabList gap={2}>
              <Tab 
                fontWeight="bold" 
                borderRadius="md" 
                px={4} 
                py={2}
                bg="gray.100" 
                color="gray.600"
                _hover={{ bg: 'gray.200' }}
                _selected={{ color: 'white', bg: 'blue.500' }}
              >
                All Inventory 
                <Badge 
                  ml={2} 
                  borderRadius="full" 
                  bg={activeTab === 'all' ? 'white' : 'gray.200'} 
                  color={activeTab === 'all' ? 'blue.500' : 'gray.600'}
                >
                  {items.length}
                </Badge>
              </Tab>
              <Tab 
                fontWeight="bold" 
                borderRadius="md" 
                px={4} 
                py={2}
                bg="gray.100" 
                color="red.600"
                _hover={{ bg: 'gray.200' }}
                _selected={{ color: 'white', bg: 'red.500' }}
              >
                Low Stock 
                <Badge 
                  ml={2} 
                  borderRadius="full" 
                  bg={activeTab === 'low' ? 'white' : 'red.100'} 
                  color={activeTab === 'low' ? 'red.500' : 'red.700'}
                >
                  {lowStockTotalCount}
                </Badge>
              </Tab>
            </TabList>
          </Tabs>

          <HStack w={{ base: '100%', lg: 'auto' }} spacing={2} align="stretch">
            <InputGroup size="sm" maxW={{ base: '100%', sm: '320px' }} flex={1}>
              <InputLeftElement pointerEvents="none" color="gray.400">🔍</InputLeftElement>
              <Input
                pl="50px"
                placeholder="Name, code, supplier..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                bg={searchTerm ? 'blue.50' : 'white'}
                borderColor={searchTerm ? 'blue.300' : 'gray.200'}
              />
              {searchTerm && (
                <Button size="xs" position="absolute" right={2} top="50%" transform="translateY(-50%)" zIndex={2} variant="ghost" onClick={() => setSearchTerm('')} h="20px" minW="20px" p={0}>X</Button>
              )}
            </InputGroup>
            <Button
              size="sm"
              colorScheme="red"
              variant="outline"
              onClick={deleteAllProducts}
              isLoading={isDeletingAll}
              loadingText="Deleting"
              isDisabled={items.length === 0}
              flexShrink={0}
            >
              Delete All
            </Button>
          </HStack>
        </Flex>

        {searchTerm && (
          <Text fontSize="xs" color="gray.500" mb={2} flexShrink={0}>
            Showing <strong>{displayedCount}</strong> result{displayedCount !== 1 ? 's' : ''} for "<strong>{searchTerm}</strong>"
          </Text>
        )}

        {!isMobile ? (
          <TableContainer flex={1} overflowY="auto" overflowX="hidden">
            <Table variant="simple" size="sm">
              <Thead bg="gray.50" position="sticky" top={0} zIndex={1}>
                <Tr>
                  <Th>Code / ID</Th>
                  <Th>Name</Th>
                  <Th display={{ base: 'none', lg: 'table-cell' }}>Supplier</Th>
                  <Th display={{ base: 'none', md: 'table-cell' }}>Category</Th>
                  <Th>Stock</Th>
                  <Th>Purchase Price</Th>
                  <Th>Selling Price</Th>
                  <Th>Actions</Th>
                </Tr>
              </Thead>
              <Tbody 
                className={activeTab === 'low' ? 'hide-normal-stock' : ''}
                sx={{ '&.hide-normal-stock .normal-stock-row': { display: 'none !important' } }}
              >
                {desktopRows}
                {displayedCount === 0 && (
                  <Tr><Td colSpan={8} textAlign="center" py={8} color="gray.400">{searchTerm ? `No results for "${searchTerm}"` : activeTab === 'low' ? 'No low stock items' : 'No items found'}</Td></Tr>
                )}
              </Tbody>
            </Table>
          </TableContainer>
        ) : (
          <VStack
            className={activeTab === 'low' ? 'hide-normal-stock' : ''}
            sx={{ 
              '&::-webkit-scrollbar': { width: '4px' }, 
              '&::-webkit-scrollbar-thumb': { bg: 'gray.300', borderRadius: 'full' },
              '&.hide-normal-stock .normal-stock-row': { display: 'none !important' } 
            }}
            flex={1}
            overflowY="auto"
            spacing={3}
            align="stretch"
          >
            {displayedCount === 0 && (
              <Text textAlign="center" color="gray.400" py={8} fontSize="sm">
                {searchTerm ? `No results for "${searchTerm}"` : activeTab === 'low' ? 'No low stock items' : 'No items found'}
              </Text>
            )}
            {mobileRows}
          </VStack>
        )}
      </Box>

      <Modal isOpen={isEditing} onClose={() => setIsEditing(false)} isCentered size={{ base: 'xs', md: 'md' }}>
        <ModalOverlay backdropFilter="blur(4px)" />
        <ModalContent mx={4}>
          <form onSubmit={updateItem}>
            <ModalHeader fontSize={{ base: 'md', md: 'lg' }}>Edit Product</ModalHeader>
            <ModalBody>
              <VStack spacing={3} align="stretch">
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={3}>
                  <FormControl isRequired>
                    <FormLabel fontSize="sm">Code / ID</FormLabel>
                    <Input size={inputSize} value={editCode} onChange={(e) => setEditCode(e.target.value)} />
                  </FormControl>
                  <FormControl>
                    <FormLabel fontSize="sm">Supplier Name</FormLabel>
                    <Input size={inputSize} value={editSupplierName} onChange={(e) => setEditSupplierName(e.target.value)} />
                  </FormControl>
                </SimpleGrid>
                <FormControl>
                  <FormLabel fontSize="sm">Name</FormLabel>
                  <Input size={inputSize} required value={editName} onChange={(e) => setEditName(e.target.value)} />
                </FormControl>
                <FormControl>
                  <FormLabel fontSize="sm">Category</FormLabel>
                  <Input size={inputSize} required value={editCategory} onChange={(e) => setEditCategory(e.target.value)} />
                </FormControl>
                <SimpleGrid columns={{ base: 1, sm: 3 }} spacing={3}>
                  <FormControl>
                    <FormLabel fontSize="sm">Purchase Price</FormLabel>
                    <Input size={inputSize} type="number" step="0.01" min="0" required value={editPurchasePrice} onChange={(e) => setEditPurchasePrice(e.target.value)} />
                  </FormControl>
                  <FormControl>
                    <FormLabel fontSize="sm">Selling Price</FormLabel>
                    <Input size={inputSize} type="number" step="0.01" min="0" required value={editPrice} onChange={(e) => setEditPrice(e.target.value)} />
                  </FormControl>
                  <FormControl>
                    <FormLabel fontSize="sm">Stock</FormLabel>
                    <Input size={inputSize} type="number" min="0" required value={editStock} onChange={(e) => setEditStock(e.target.value)} />
                  </FormControl>
                </SimpleGrid>
              </VStack>
            </ModalBody>
            <ModalFooter gap={2}>
              <Button variant="ghost" size={inputSize} onClick={() => setIsEditing(false)}>Cancel</Button>
              <Button colorScheme="blue" size={inputSize} type="submit">Save Changes</Button>
            </ModalFooter>
          </form>
        </ModalContent>
      </Modal>
    </Flex>
  );
}