import {
  collection,
  deleteDoc,
  doc,
  getDoc,
  getDocs,
  limit,
  query,
  setDoc,
  updateDoc,
  where
} from 'firebase/firestore';
import { auth, db } from './firebaseConfig';

export const USERS_COLLECTION = 'users';
export const USERNAME_LOGIN_COLLECTION = 'username_logins';
export const ADMIN_ROLE = 'Admin';

export const STAFF_ROLES = [
  'Cashier',
  'Shopee',
  'Cashier+Shopee',
  ADMIN_ROLE
];

export const cleanUsernameValue = (value) =>
  String(value || '').trim().toLowerCase().replace(/\s+/g, '');

export const cleanEmailValue = (value) =>
  String(value || '').trim().toLowerCase();

export const validateUsername = (value) => {
  const username = cleanUsernameValue(value);

  if (username.length < 4 || username.length > 32) {
    return 'Username must be 4 to 32 characters.';
  }

  if (!/^[a-z0-9._-]+$/.test(username)) {
    return 'Use only letters, numbers, dot, dash, or underscore.';
  }

  return '';
};

export const validateEmail = (value) => {
  const email = cleanEmailValue(value);

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return 'Enter a valid email address.';
  }

  return '';
};

export const getEmailFromLoginIdentifier = async (value) => {
  const identifier = String(value || '').trim();

  if (!identifier) {
    throw new Error('Enter your username or email.');
  }

  if (identifier.includes('@')) {
    const cleanEmail = cleanEmailValue(identifier);
    const emailError = validateEmail(cleanEmail);

    if (emailError) throw new Error(emailError);
    return cleanEmail;
  }

  const cleanUsername = cleanUsernameValue(identifier);
  const usernameError = validateUsername(cleanUsername);

  if (usernameError) throw new Error(usernameError);

  const lookupSnapshot = await getDoc(
    doc(db, USERNAME_LOGIN_COLLECTION, cleanUsername)
  );

  if (lookupSnapshot.exists()) {
    const lookup = lookupSnapshot.data();

    if (lookup.isActive === false || lookup.accountStatus === 'disabled') {
      throw new Error('This staff account is disabled.');
    }

    const lookupEmail = cleanEmailValue(lookup.email || lookup.emailLower);

    if (lookupEmail) return lookupEmail;
  }

  let snapshot = await getDocs(
    query(
      collection(db, USERS_COLLECTION),
      where('usernameLower', '==', cleanUsername),
      limit(1)
    )
  );

  if (snapshot.empty) {
    snapshot = await getDocs(collection(db, USERS_COLLECTION));
  }

  if (snapshot.empty) {
    throw new Error('No active staff account uses this username.');
  }

  const matchedDoc = snapshot.docs.find((userDoc) => {
    const profile = userDoc.data();
    return cleanUsernameValue(profile.usernameLower || profile.username) === cleanUsername;
  });

  if (!matchedDoc) {
    throw new Error('No active staff account uses this username.');
  }

  const profile = matchedDoc.data();

  if (profile.isActive === false || profile.accountStatus === 'disabled') {
    throw new Error('This staff account is disabled.');
  }

  const email = cleanEmailValue(profile.email || profile.emailLower);

  if (!email) {
    throw new Error('This username has no email saved for Firebase login.');
  }

  return email;
};

export const validatePassword = (value) => {
  if (String(value || '').length < 6) {
    return 'Password must be at least 6 characters.';
  }

  return '';
};

const mapAuthRestError = (message) => {
  const authErrors = {
    EMAIL_EXISTS: 'This email already exists in Firebase Auth.',
    INVALID_EMAIL: 'Enter a valid email address.',
    EMAIL_NOT_FOUND: 'No Firebase Auth account uses this email address.',
    OPERATION_NOT_ALLOWED: 'Enable Email/Password sign-in in Firebase Authentication.',
    WEAK_PASSWORD: 'Password must be at least 6 characters.',
    TOO_MANY_ATTEMPTS_TRY_LATER: 'Too many attempts. Try again later.'
  };

  return authErrors[message] || message || 'Firebase Auth request failed.';
};

export const createAuthUserWithoutSigningOut = async ({
  email,
  password
}) => {
  const cleanEmail = cleanEmailValue(email);
  const apiKey = auth?.app?.options?.apiKey;

  if (!apiKey) {
    throw new Error('Firebase API key was not found in firebaseConfig.');
  }

  const response = await fetch(
    `https://identitytoolkit.googleapis.com/v1/accounts:signUp?key=${apiKey}`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        email: cleanEmail,
        password,
        returnSecureToken: false
      })
    }
  );
  const data = await response.json();

  if (!response.ok) {
    throw new Error(mapAuthRestError(data?.error?.message));
  }

  return {
    uid: data.localId,
    email: cleanEmailValue(data.email || cleanEmail)
  };
};

export const sendPasswordResetEmailFallback = async (email) => {
  const cleanEmail = cleanEmailValue(email);
  const apiKey = auth?.app?.options?.apiKey;

  if (!apiKey) {
    throw new Error('Firebase API key was not found in firebaseConfig.');
  }

  const response = await fetch(
    `https://identitytoolkit.googleapis.com/v1/accounts:sendOobCode?key=${apiKey}`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        requestType: 'PASSWORD_RESET',
        email: cleanEmail
      })
    }
  );
  const data = await response.json();

  if (!response.ok) {
    throw new Error(mapAuthRestError(data?.error?.message));
  }

  return data;
};

export const getUserProfile = async (uid) => {
  if (!uid) return null;

  const snapshot = await getDoc(doc(db, USERS_COLLECTION, uid));

  if (!snapshot.exists()) return null;

  return {
    uid: snapshot.id,
    ...snapshot.data()
  };
};

export const getStaffUsers = async () => {
  const snapshot = await getDocs(collection(db, USERS_COLLECTION));

  return snapshot.docs
    .map((userDoc) => ({
      uid: userDoc.id,
      ...userDoc.data()
    }))
    .sort((first, second) =>
      (first.username || '').localeCompare(second.username || '')
    );
};

export const hasActiveAdmin = async () => {
  const users = await getStaffUsers();

  return users.some(
    (user) => user.role === ADMIN_ROLE && user.isActive !== false
  );
};

export const saveUserProfile = async ({
  uid,
  username,
  email,
  role,
  existingUser = null,
  isActive = true
}) => {
  const now = new Date().toISOString();
  const cleanUsername = cleanUsernameValue(username);
  const cleanEmail = cleanEmailValue(email);
  const oldUsername = cleanUsernameValue(existingUser?.username || existingUser?.usernameLower);

  await setDoc(
    doc(db, USERS_COLLECTION, uid),
    {
      uid,
      username: cleanUsername,
      usernameLower: cleanUsername,
      email: cleanEmail,
      emailLower: cleanEmail,
      role,
      isActive,
      accountStatus: isActive ? 'active' : 'disabled',
      createdAt: existingUser?.createdAt || now,
      updatedAt: now,
      lastLogin: existingUser?.lastLogin || null
    },
    { merge: true }
  );

  await setDoc(
    doc(db, USERNAME_LOGIN_COLLECTION, cleanUsername),
    {
      uid,
      username: cleanUsername,
      usernameLower: cleanUsername,
      email: cleanEmail,
      emailLower: cleanEmail,
      isActive,
      accountStatus: isActive ? 'active' : 'disabled',
      updatedAt: now
    },
    { merge: true }
  );

  if (oldUsername && oldUsername !== cleanUsername) {
    await deleteDoc(doc(db, USERNAME_LOGIN_COLLECTION, oldUsername));
  }
};

export const touchLastLogin = async (uid) => {
  if (!uid) return;

  await updateDoc(doc(db, USERS_COLLECTION, uid), {
    lastLogin: new Date().toISOString()
  });
};

export const deactivateUserProfile = async (uid) => {
  const userRef = doc(db, USERS_COLLECTION, uid);
  const profileSnapshot = await getDoc(userRef);
  const profile = profileSnapshot.exists() ? profileSnapshot.data() : null;

  await updateDoc(doc(db, USERS_COLLECTION, uid), {
    isActive: false,
    accountStatus: 'disabled',
    deletedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  });

  const username = cleanUsernameValue(profile?.usernameLower || profile?.username);

  if (!username) return;

  const lookupRef = doc(db, USERNAME_LOGIN_COLLECTION, username);
  const lookupSnapshot = await getDoc(lookupRef);

  if (!lookupSnapshot.exists()) return;

  if (lookupSnapshot.data()?.uid === uid) {
    await updateDoc(lookupRef, {
      isActive: false,
      accountStatus: 'disabled',
      updatedAt: new Date().toISOString()
    });
  }
};
