import React, { useEffect, useState } from 'react';
import {
  Box,
  Heading,
  Input,
  Button,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Badge,
  useToast,
  FormControl,
  FormLabel,
  Select,
  Grid,
  Text
} from '@chakra-ui/react';
import {
  collection,
  onSnapshot
} from 'firebase/firestore';
import { sendPasswordResetEmail } from 'firebase/auth';
import { auth, db } from './firebaseConfig';
import { MAIN_ACCOUNT_EMAIL } from './appEmailConfig';
import {
  ADMIN_ROLE,
  STAFF_ROLES,
  USERS_COLLECTION,
  cleanEmailValue,
  cleanUsernameValue,
  createAuthUserWithoutSigningOut,
  deactivateUserProfile,
  sendPasswordResetEmailFallback,
  saveUserProfile,
  validateEmail,
  validatePassword,
  validateUsername
} from './dbStaffAuth';

const isAdminUser = (user) => user?.role === ADMIN_ROLE;

const createTemporaryPassword = () => {
  const randomPart =
    typeof crypto !== 'undefined' && crypto.getRandomValues
      ? Array.from(crypto.getRandomValues(new Uint32Array(3)))
          .map((value) => value.toString(36))
          .join('')
      : Math.random().toString(36).slice(2);

  return `Temp-${Date.now()}-${randomPart}-A1!`;
};

const sendPasswordResetWithFallback = async (email) => {
  try {
    await sendPasswordResetEmail(auth, email);
  } catch {
    await sendPasswordResetEmailFallback(email);
  }
};

const getUsernameFromEmail = (value) => {
  const emailName = cleanEmailValue(value).split('@')[0] || '';
  const aliasName = emailName.includes('+') ? emailName.split('+').pop() : emailName;
  const cleanUsername = cleanUsernameValue(aliasName);

  return cleanUsername.length >= 4 ? cleanUsername : '';
};

const getEmailForUsername = (value) => {
  const cleanUsername = cleanUsernameValue(value);
  const cleanMainEmail = cleanEmailValue(MAIN_ACCOUNT_EMAIL);
  const [name, domain] = cleanMainEmail.split('@');
  const baseName = String(name || '').split('+')[0];

  if (!cleanUsername || !baseName || !domain) return '';

  return `${baseName}+${cleanUsername}@${domain}`;
};

const getEmailAliasHelp = () => {
  const sampleEmail = getEmailForUsername('admin');

  return sampleEmail ? `Example: ${sampleEmail}` : 'Set MAIN_ACCOUNT_EMAIL in appEmailConfig.js.';
};

export default function UsersManager({ currentUserProfile = null }) {
  const [users, setUsers] = useState([]);

  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [wasUsernameEdited, setWasUsernameEdited] = useState(false);
  const [wasEmailEdited, setWasEmailEdited] = useState(false);
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('Cashier');

  const [isCreating, setIsCreating] = useState(false);
  const [isLoadingUsers, setIsLoadingUsers] = useState(true);

  const [editingUid, setEditingUid] = useState(null);
  const [editUsername, setEditUsername] = useState('');
  const [editEmail, setEditEmail] = useState('');
  const [editRole, setEditRole] = useState('Cashier');

  const [savingUid, setSavingUid] = useState(null);
  const [deletingUid, setDeletingUid] = useState(null);
  const [enablingUid, setEnablingUid] = useState(null);
  const [resettingUid, setResettingUid] = useState(null);

  const toast = useToast();

  useEffect(() => {
    setIsLoadingUsers(true);

    const unsub = onSnapshot(
      collection(db, USERS_COLLECTION),
      (snapshot) => {
        setUsers(
          snapshot.docs
            .map((docSnap) => ({
              uid: docSnap.id,
              ...docSnap.data()
            }))
            .sort((first, second) =>
              (first.username || '').localeCompare(second.username || '')
            )
        );
        setIsLoadingUsers(false);
      },
      (error) => {
        setIsLoadingUsers(false);
        toast({
          title: 'Users load failed',
          description: error.message,
          status: 'error',
          position: 'top'
        });
      }
    );

    return () => unsub();
  }, [toast]);

  const adminUsers = users.filter((user) => isAdminUser(user) && user.isActive !== false);
  const hasAdminUser = adminUsers.length > 0;
  const isLastAdminUser = (user) =>
    isAdminUser(user) && user.isActive !== false && adminUsers.length <= 1;

  const handleCreateUser = async (e) => {
    e.preventDefault();

    const cleanUsername = cleanUsernameValue(username);
    const cleanEmail = cleanEmailValue(email);
    const usernameError = validateUsername(cleanUsername);
    const emailError = validateEmail(cleanEmail);
    const passwordError = validatePassword(password);

    if (usernameError || emailError || passwordError) {
      toast({
        title: 'Cannot create user',
        description: usernameError || emailError || passwordError,
        status: 'error',
        position: 'top'
      });
      return;
    }

    const usernameExists = users.some(
      (user) =>
        cleanUsernameValue(user.username || '') === cleanUsername
    );
    const emailExists = users.some(
      (user) =>
        cleanEmailValue(user.email || '') === cleanEmail
    );

    if (usernameExists || emailExists) {
      toast({
        title: usernameExists ? 'Username already exists' : 'Email already exists',
        status: 'error',
        position: 'top'
      });
      return;
    }

    setIsCreating(true);

    try {
      const assignedRole = hasAdminUser ? role : ADMIN_ROLE;
      const authUser = await createAuthUserWithoutSigningOut({
        email: cleanEmail,
        password
      });

      await saveUserProfile({
        uid: authUser.uid,
        username: cleanUsername,
        email: cleanEmail,
        role: assignedRole,
        isActive: true
      });

      toast({
        title: 'User created',
        description: 'Firebase Auth account and staff profile were created.',
        status: 'success',
        position: 'top'
      });

      setUsername('');
      setEmail('');
      setWasUsernameEdited(false);
      setWasEmailEdited(false);
      setPassword('');
      setRole('Cashier');
    } catch (error) {
      if (
        error?.code === 'auth/email-already-in-use' ||
        /email already exists/i.test(error?.message || '')
      ) {
        try {
          await sendPasswordResetWithFallback(cleanEmail);

          toast({
            title: 'Account already exists',
            description: `A password reset link was sent to ${cleanEmail}.`,
            status: 'info',
            duration: 6000,
            position: 'top'
          });
        } catch (resetError) {
          toast({
            title: 'Account exists, reset failed',
            description: resetError.message,
            status: 'error',
            duration: 6000,
            position: 'top'
          });
        }
        return;
      }

      toast({
        title: 'Create failed',
        description: error.message,
        status: 'error',
        duration: 5000,
        position: 'top'
      });
    } finally {
      setIsCreating(false);
    }
  };

  const startEditUser = (user) => {
    setEditingUid(user.uid);
    setEditUsername(user.username || '');
    setEditEmail(user.email || '');
    setEditRole(user.role || 'Cashier');
  };

  const cancelEditUser = () => {
    setEditingUid(null);
    setEditUsername('');
    setEditEmail('');
    setEditRole('Cashier');
  };

  const migrateUserEmail = async ({
    user,
    cleanUsername,
    cleanEmail,
    role
  }) => {
    const confirmed = window.confirm(
      `Change login email for ${user.username}?\n\nOld email: ${user.email}\nNew email: ${cleanEmail}\n\nA new Firebase login will be created for the new email, the old staff profile will be disabled, and a password reset link will be sent to the new email.`
    );

    if (!confirmed) return { cancelled: true };

    let authUser = null;

    try {
      authUser = await createAuthUserWithoutSigningOut({
        email: cleanEmail,
        password: createTemporaryPassword()
      });
    } catch (error) {
      if (!/email already exists/i.test(error?.message || '')) {
        throw error;
      }

      await saveUserProfile({
        uid: user.uid,
        username: cleanUsername,
        email: cleanEmail,
        role,
        existingUser: user,
        isActive: user.isActive !== false
      });

      try {
        await sendPasswordResetWithFallback(cleanEmail);
        return { resetSent: true, usedExistingAuthEmail: true };
      } catch (resetError) {
        return { resetSent: false, resetError, usedExistingAuthEmail: true };
      }
    }

    await saveUserProfile({
      uid: authUser.uid,
      username: cleanUsername,
      email: cleanEmail,
      role,
      existingUser: user,
      isActive: true
    });

    await deactivateUserProfile(user.uid);

    try {
      await sendPasswordResetWithFallback(cleanEmail);
      return { resetSent: true };
    } catch (resetError) {
      return { resetSent: false, resetError };
    }
  };

  const handleSaveUser = async (user) => {
    if (!user?.uid) return;

    const cleanEditUsername = cleanUsernameValue(editUsername);
    const cleanEditEmail = cleanEmailValue(editEmail);
    const usernameError = validateUsername(cleanEditUsername);
    const emailError = validateEmail(cleanEditEmail);

    if (usernameError || emailError) {
      return toast({
        title: usernameError ? 'Invalid username' : 'Invalid email',
        description: usernameError || emailError,
        status: 'error',
        position: 'top'
      });
    }

    if (isLastAdminUser(user) && editRole !== ADMIN_ROLE) {
      return toast({
        title: 'At least one admin required',
        description: 'Create another Admin before changing this role.',
        status: 'error',
        position: 'top'
      });
    }

    const usernameTaken = users.some(
      (staffUser) =>
        staffUser.uid !== user.uid &&
        cleanUsernameValue(staffUser.username || '') === cleanEditUsername
    );
    const emailChanged = cleanEditEmail !== cleanEmailValue(user.email);
    const emailTaken = users.some(
      (staffUser) =>
        staffUser.uid !== user.uid &&
        staffUser.isActive !== false &&
        cleanEmailValue(staffUser.email || '') === cleanEditEmail
    );

    if (usernameTaken || emailTaken) {
      return toast({
        title: usernameTaken ? 'Username already exists' : 'Email already exists',
        status: 'error',
        position: 'top'
      });
    }

    setSavingUid(user.uid);

    try {
      if (emailChanged) {
        const result = await migrateUserEmail({
          user,
          cleanUsername: cleanEditUsername,
          cleanEmail: cleanEditEmail,
          role: editRole
        });

        if (result.cancelled) return;

        toast({
          title: result.resetSent
            ? result.usedExistingAuthEmail
              ? 'Email synced'
              : 'Email changed'
            : result.usedExistingAuthEmail
              ? 'Email synced, reset failed'
              : 'Email changed, reset failed',
          description: result.resetSent
            ? `Password reset link sent to ${cleanEditEmail}.`
            : result.resetError?.message || 'Send a reset link again from this staff row.',
          status: result.resetSent ? 'success' : 'warning',
          duration: 6000,
          position: 'top'
        });

        cancelEditUser();
        return;
      }

      await saveUserProfile({
        uid: user.uid,
        username: cleanEditUsername,
        email: cleanEditEmail,
        role: editRole,
        existingUser: user,
        isActive: user.isActive !== false // Maintains their disabled status if they were disabled
      });

      toast({
        title: 'User updated',
        status: 'success',
        position: 'top'
      });

      cancelEditUser();
    } catch (error) {
      toast({
        title: 'Update failed',
        description: error.message,
        status: 'error',
        position: 'top'
      });
    } finally {
      setSavingUid(null);
    }
  };

  const handleDisableUser = async (user) => {
    if (!user?.uid) return;

    if (currentUserProfile?.uid === user.uid) {
      return toast({
        title: 'Cannot disable yourself',
        status: 'error',
        position: 'top'
      });
    }

    if (isLastAdminUser(user)) {
      return toast({
        title: 'At least one admin required',
        description: 'Create another Admin before disabling this account.',
        status: 'error',
        position: 'top'
      });
    }

    const confirmed = window.confirm(
      `Disable ${user.username}? They will no longer be able to use the app.`
    );

    if (!confirmed) return;

    setDeletingUid(user.uid);

    try {
      await deactivateUserProfile(user.uid);

      toast({
        title: 'User disabled',
        status: 'success',
        position: 'top'
      });
    } catch (error) {
      toast({
        title: 'Disable failed',
        description: error.message,
        status: 'error',
        position: 'top'
      });
    } finally {
      setDeletingUid(null);
    }
  };

  const handleEnableUser = async (user) => {
    if (!user?.uid) return;

    setEnablingUid(user.uid);

    try {
      await saveUserProfile({
        uid: user.uid,
        username: user.username,
        email: user.email,
        role: user.role,
        existingUser: user,
        isActive: true
      });

      toast({
        title: 'User enabled',
        description: `${user.username} can now use the app again.`,
        status: 'success',
        position: 'top'
      });
    } catch (error) {
      toast({
        title: 'Enable failed',
        description: error.message,
        status: 'error',
        position: 'top'
      });
    } finally {
      setEnablingUid(null);
    }
  };

  const handleResetPassword = async (user) => {
    const cleanEmail = cleanEmailValue(user?.email);

    if (!cleanEmail) {
      return toast({
        title: 'Missing email',
        status: 'error',
        position: 'top'
      });
    }

    setResettingUid(user.uid);

    try {
      await sendPasswordResetWithFallback(cleanEmail);

      toast({
        title: 'Password reset sent',
        description: `Check ${cleanEmail}.`,
        status: 'success',
        duration: 4000,
        position: 'top'
      });
    } catch (error) {
      toast({
        title: 'Reset failed',
        description: error.message,
        status: 'error',
        duration: 5000,
        position: 'top'
      });
    } finally {
      setResettingUid(null);
    }
  };

  return (
    <Grid
      templateColumns={{
        base: '1fr',
        lg: '1fr 2fr'
      }}
      gap={4}
      w="100%"
      maxW="100%"
      minW={0}
      alignItems="start"
    >
      <Box
        minW={0}
        maxH={{
          base: 'none',
          lg: 'calc(100vh - 220px)'
        }}
        overflowY={{
          base: 'visible',
          lg: 'auto'
        }}
        pr={{
          base: 0,
          lg: 1
        }}
      >
        <Box
          bg="white"
          p={{ base: 3, md: 4 }}
          borderRadius="lg"
          shadow="sm"
          mb={4}
          minW={0}
        >
          <Heading size="md" mb={3}>
            Firebase Staff Auth
          </Heading>

          <Text mb={2} fontSize="sm" color="gray.600">
            Staff sign in with username and password. The saved email is still
            used behind the scenes for Firebase Auth and password resets.
          </Text>

          <Text fontSize="xs" color="gray.500">
            Changing a staff email creates a new Firebase login for the new
            email, disables the old staff profile, and sends the reset link to
            the new email.
          </Text>
        </Box>

        <Box
          bg="white"
          p={{ base: 3, md: 4 }}
          borderRadius="lg"
          shadow="sm"
          minW={0}
        >
          <Heading size="md" mb={4}>
            Add New User
          </Heading>

          <form onSubmit={handleCreateUser}>
            <FormControl mb={3} isRequired>
              <FormLabel fontSize="sm">
                Username
              </FormLabel>

              <Input
                value={username}
                onChange={(e) => {
                  const nextUsername = e.target.value;
                  setWasUsernameEdited(true);
                  setUsername(nextUsername);

                  if (!wasEmailEdited) {
                    setEmail(getEmailForUsername(nextUsername));
                  }
                }}
                size="sm"
                placeholder="Type username, email fills automatically"
              />
            </FormControl>

            <FormControl mb={3} isRequired>
              <FormLabel fontSize="sm">
                Email
              </FormLabel>

              <Input
                type="email"
                value={email}
                onChange={(e) => {
                  const nextEmail = e.target.value;
                  setWasEmailEdited(true);
                  setEmail(nextEmail);

                  if (!wasUsernameEdited) {
                    setUsername(getUsernameFromEmail(nextEmail));
                  }
                }}
                size="sm"
                placeholder={getEmailAliasHelp()}
              />
              <Text mt={1} fontSize="xs" color="gray.500">
                Auto-generated from username using {MAIN_ACCOUNT_EMAIL}.
              </Text>
            </FormControl>

            <FormControl mb={3} isRequired>
              <FormLabel fontSize="sm">
                Password
              </FormLabel>

              <Input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                size="sm"
                minLength={6}
                placeholder="Minimum 6 characters"
              />
            </FormControl>

            <FormControl mb={5} isRequired>
              <FormLabel fontSize="sm">
                Role
              </FormLabel>

              <Select
                value={hasAdminUser ? role : ADMIN_ROLE}
                onChange={(e) => setRole(e.target.value)}
                size="sm"
                isDisabled={!hasAdminUser}
              >
                {STAFF_ROLES.map((staffRole) => (
                  <option key={staffRole} value={staffRole}>
                    {staffRole === 'Cashier+Shopee' ? 'Cashier + Shopee' : staffRole}
                  </option>
                ))}
              </Select>

              {!hasAdminUser && (
                <Text mt={2} fontSize="xs" color="gray.600">
                  First account must be Admin.
                </Text>
              )}
            </FormControl>

            <Button
              type="submit"
              colorScheme="blue"
              w="100%"
              isLoading={isCreating}
            >
              Create Firebase Account
            </Button>
          </form>
        </Box>
      </Box>

      <Box
        bg="white"
        p={{ base: 3, md: 4 }}
        borderRadius="lg"
        shadow="sm"
        minW={0}
        maxW="100%"
        overflow="hidden"
      >
        <Heading size="md" mb={4}>
          Current Staff
        </Heading>

        <Box
          maxW="100%"
          maxH={{
            base: '65vh',
            lg: 'calc(100vh - 220px)'
          }}
          overflowX="auto"
          overflowY="auto"
          pb={2}
        >
          <Table
            size="sm"
            minW={{
              base: '980px',
              md: '1040px'
            }}
          >
            <Thead>
              <Tr>
                <Th whiteSpace="nowrap">Username</Th>
                <Th whiteSpace="nowrap">Email</Th>
                <Th whiteSpace="nowrap">Role</Th>
                <Th whiteSpace="nowrap">Status</Th>
                <Th whiteSpace="nowrap">Actions</Th>
              </Tr>
            </Thead>

            <Tbody>
              {isLoadingUsers && (
                <Tr>
                  <Td colSpan={5}>
                    <Text color="gray.500" fontSize="sm">
                      Loading staff users...
                    </Text>
                  </Td>
                </Tr>
              )}

              {!isLoadingUsers && users.length === 0 && (
                <Tr>
                  <Td colSpan={5}>
                    <Text color="gray.500" fontSize="sm">
                      No staff users found.
                    </Text>
                  </Td>
                </Tr>
              )}

              {users.map((user) => {
                const isEditing = editingUid === user.uid;
                const isActiveUser = user.isActive !== false;

                return (
                  <Tr key={user.uid} opacity={isActiveUser ? 1 : 0.6}>
                    <Td minW="170px">
                      {isEditing ? (
                        <Input
                          value={editUsername}
                          onChange={(e) => setEditUsername(e.target.value)}
                          size="xs"
                        />
                      ) : (
                        <Text fontSize="sm" fontWeight="medium">
                          {user.username}
                        </Text>
                      )}
                    </Td>

                    <Td minW="240px">
                      {isEditing ? (
                        <Input
                          value={editEmail}
                          onChange={(e) => setEditEmail(e.target.value)}
                          size="xs"
                          type="email"
                        />
                      ) : (
                        <Text fontSize="sm" color="gray.700">
                          {user.email}
                        </Text>
                      )}
                    </Td>

                    <Td minW="150px">
                      {isEditing ? (
                        <Select
                          value={editRole}
                          onChange={(e) => setEditRole(e.target.value)}
                          size="xs"
                        >
                          {STAFF_ROLES.map((staffRole) => (
                            <option key={staffRole} value={staffRole}>
                              {staffRole === 'Cashier+Shopee' ? 'Cashier + Shopee' : staffRole}
                            </option>
                          ))}
                        </Select>
                      ) : (
                        <Badge colorScheme="blue">
                          {user.role}
                        </Badge>
                      )}
                    </Td>

                    <Td minW="110px">
                      {isActiveUser ? (
                        <Badge colorScheme="green">Active</Badge>
                      ) : (
                        <Badge colorScheme="red">Disabled</Badge>
                      )}
                    </Td>

                    <Td minW="330px">
                      {isEditing ? (
                        <Box display="flex" gap={2} flexWrap="wrap">
                          <Button
                            size="xs"
                            colorScheme="green"
                            onClick={() => handleSaveUser(user)}
                            isLoading={savingUid === user.uid}
                          >
                            Save
                          </Button>

                          <Button size="xs" onClick={cancelEditUser}>
                            Cancel
                          </Button>
                        </Box>
                      ) : (
                        <Box display="flex" gap={2} flexWrap="wrap">
                          <Button
                            size="xs"
                            onClick={() => startEditUser(user)}
                          >
                            Edit
                          </Button>

                          <Button
                            size="xs"
                            colorScheme="orange"
                            onClick={() => handleResetPassword(user)}
                            isLoading={resettingUid === user.uid}
                          >
                            Reset Password
                          </Button>

                          {isActiveUser ? (
                            <Button
                              size="xs"
                              colorScheme="red"
                              onClick={() => handleDisableUser(user)}
                              isLoading={deletingUid === user.uid}
                            >
                              Disable
                            </Button>
                          ) : (
                            <Button
                              size="xs"
                              colorScheme="green"
                              onClick={() => handleEnableUser(user)}
                              isLoading={enablingUid === user.uid}
                            >
                              Enable
                            </Button>
                          )}
                        </Box>
                      )}
                    </Td>
                  </Tr>
                );
              })}
            </Tbody>
          </Table>
        </Box>
      </Box>
    </Grid>
  );
}